window.IAHI.audioManifest = {"v8":{"file":"v8.mp3","duration":231.28799999999987,"chapters":[{"title":"Ocho minutos para un flujo","start":0},{"title":"La rúbrica","start":82.5},{"title":"En el caso de la informalidad laboral","start":160.97599999999997}],"scenes":[{"id":"gancho","start":0,"end":15.408},{"id":"entrega","start":15.408,"end":39.403999999999996},{"id":"estructura","start":39.403999999999996,"end":61.263999999999996},{"id":"flujo","start":61.263999999999996,"end":82.5},{"id":"rubrica","start":82.5,"end":119.356},{"id":"galeria","start":119.356,"end":140.97599999999997},{"id":"transferible","start":140.97599999999997,"end":154.97599999999997},{"id":"caso","start":160.97599999999997,"end":180.98199999999994},{"id":"declaracion","start":180.98199999999994,"end":205.1119999999999},{"id":"ideas","start":205.1119999999999,"end":231.28799999999987}],"lines":[{"scene":"gancho","index":0,"voice":"narrador","start":0,"dur":13.608,"chunks":[{"text":"¿Cómo mostrar, en pocos minutos, que su uso de IA es válido,","start":0,"end":4.169916},{"text":"reproducible y responsable?","start":4.169916,"end":6.709166},{"text":"En la última sesión,","start":6.709166,"end":8.16325},{"text":"cada participante presenta su flujo de trabajo y cómo responde a los seis ejes.","start":8.16325,"end":13.608}]},{"scene":"entrega","index":0,"voice":"narrador","start":0,"dur":12.696,"chunks":[{"text":"Entregue 48 horas antes de la sesión, en la carpeta compartida:","start":0,"end":4.769375},{"text":"el diagrama del flujo en una página, hasta 6 diapositivas,","start":4.769375,"end":8.672458},{"text":"la bitácora completa y la declaración de uso de IA.","start":8.672458,"end":12.696}]},{"scene":"entrega","index":1,"voice":"narrador","start":0,"dur":9,"chunks":[{"text":"Así, si falla su conexión,","start":0,"end":2.294916},{"text":"el docente puede proyectar las diapositivas que usted entregó,","start":2.294916,"end":5.777041},{"text":"y usted sigue por audio o por teléfono.","start":5.777041,"end":9}]},{"scene":"estructura","index":0,"voice":"narrador","start":0,"dur":12.936,"chunks":[{"text":"Según el programa del curso, cada presentación dura 8 minutos:","start":0,"end":4.361208},{"text":"1 para el proyecto y la pregunta, 3 para el flujo, 2 para la evidencia,","start":4.361208,"end":9.106125},{"text":"1 para las implicaciones y 1 para la declaración.","start":9.106125,"end":12.936}]},{"scene":"estructura","index":1,"voice":"narrador","start":0,"dur":6.624,"chunks":[{"text":"El temporizador avisa a los 6 y a los 8 minutos,","start":0,"end":3.379083},{"text":"y luego vienen 2 minutos de preguntas.","start":3.379083,"end":6.624}]},{"scene":"flujo","index":0,"voice":"narrador","start":0,"dur":9.432,"chunks":[{"text":"En el flujo, muestre las etapas de su investigación y, en cada una,","start":0,"end":4.629083},{"text":"qué herramienta usa, para qué y dónde está el punto de control humano.","start":4.629083,"end":9.432}]},{"scene":"flujo","index":1,"voice":"narrador","start":0,"dur":9.504,"chunks":[{"text":"En la evidencia, muestre un resultado real obtenido con el flujo,","start":0,"end":4.271958},{"text":"en una captura o una demostración corta, y cómo lo verificó o validó.","start":4.271958,"end":9.504}]},{"scene":"rubrica","index":0,"voice":"narrador","start":0,"dur":13.728,"chunks":[{"text":"La rúbrica tiene cinco criterios de 20 % cada uno: pertinencia;","start":0,"end":4.947958},{"text":"validez y verificación; reproducibilidad y transparencia; ética,","start":4.947958,"end":9.322958},{"text":"protección de datos y equidad; y claridad y transferibilidad.","start":9.322958,"end":13.728}]},{"scene":"rubrica","index":1,"voice":"narrador","start":0,"dur":14.976,"chunks":[{"text":"Cada criterio se califica de 1 a 4.","start":0,"end":3.316333},{"text":"En el criterio de validez, por ejemplo,","start":3.316333,"end":5.982125},{"text":"el nivel 4 pide puntos de control humano y referencias verificadas;","start":5.982125,"end":10.331625},{"text":"el nivel 1 corresponde a aceptar resultados de IA sin verificar.","start":10.331625,"end":14.976}]},{"scene":"rubrica","index":2,"voice":"narrador","start":0,"dur":5.352,"chunks":[{"text":"Dos comentaristas y el docente califican cada presentación en un formulario.","start":0,"end":5.352}]},{"scene":"galeria","index":0,"voice":"narrador","start":0,"dur":10.224,"chunks":[{"text":"Si hay más de 9 presentaciones, el curso usa una galería virtual:","start":0,"end":4.705625},{"text":"cada equipo sube su diagrama y un video de 3 minutos a un tablero compartido.","start":4.705625,"end":10.224}]},{"scene":"galeria","index":1,"voice":"narrador","start":0,"dur":9.096,"chunks":[{"text":"En salas paralelas de tres equipos, cada uno presenta en 5 minutos y,","start":0,"end":4.858666},{"text":"con dos rondas, recibe comentarios de seis colegas.","start":4.858666,"end":9.096}]},{"scene":"transferible","index":0,"voice":"narrador","start":0,"dur":10.752,"chunks":[{"text":"En claridad,","start":0,"end":1.121416},{"text":"el nivel más alto es","start":1.121416,"end":2.307666},{"text":"que otra persona pueda replicar el flujo con lo que usted presenta.","start":2.307666,"end":6.811208},{"text":"Y diga también qué decidió su equipo no hacer con IA.","start":6.811208,"end":10.752}]},{"scene":"caso","index":0,"voice":"mariana","start":0,"dur":12.024,"chunks":[{"text":"Nuestro flujo tiene cinco etapas.","start":0,"end":2.975},{"text":"En la de entrevistas,","start":2.975,"end":4.55},{"text":"el punto de control es la validación contra nuestra codificación humana,","start":4.55,"end":8.75},{"text":"antes de aplicar el libro de códigos al resto.","start":8.75,"end":12.024}]},{"scene":"caso","index":1,"voice":"amparo","start":0,"dur":5.832,"chunks":[{"text":"Y decidimos no usar IA para interpretar las entrevistas","start":0,"end":3.060208},{"text":"ni para redactar los resultados.","start":3.060208,"end":5.832}]},{"scene":"declaracion","index":0,"voice":"julian","start":0,"dur":4.44,"chunks":[{"text":"Y la declaración la dejamos para el final, como un trámite del anexo.","start":0,"end":4.44}]},{"scene":"declaracion","index":1,"voice":"narrador","start":0,"dur":11.664,"chunks":[{"text":"No es un trámite: dice qué herramientas se usaron, para qué tarea, quién verificó,","start":0,"end":5.458166},{"text":"qué resultado dio la validación,","start":5.458166,"end":7.473458},{"text":"qué no se hizo con IA y qué pasó con los datos personales.","start":7.473458,"end":11.664}]},{"scene":"declaracion","index":2,"voice":"narrador","start":0,"dur":5.376,"chunks":[{"text":"Las implicaciones y su documentación son parte del método, no un anexo.","start":0,"end":5.376}]},{"scene":"ideas","index":0,"voice":"narrador","start":0,"dur":7.368,"chunks":[{"text":"Tres ideas para llevarse.","start":0,"end":2.46175},{"text":"La IA es una herramienta estadística poderosa con límites conocidos.","start":2.46175,"end":7.368}]},{"scene":"ideas","index":1,"voice":"narrador","start":0,"dur":5.088,"chunks":[{"text":"El criterio, la verificación y la validación son de quien investiga.","start":0,"end":5.088}]},{"scene":"ideas","index":2,"voice":"narrador","start":0,"dur":10.92,"chunks":[{"text":"Y las implicaciones y su documentación son parte del método, no un anexo.","start":0,"end":5.497458},{"text":"El canal del curso queda abierto para compartir flujos, skills y problemas.","start":5.497458,"end":10.92}]}],"checkpoints":[],"pauses":[{"after":"transferible","start":154.97599999999997,"end":160.97599999999997}]},"v1":{"file":"v1.mp3","duration":586.8540000000003,"chapters":[{"title":"¿Qué es un modelo de IA?","start":0},{"title":"Setenta años en una línea","start":142.16000000000003},{"title":"Código abierto, pesos abiertos o cerrado","start":258.548},{"title":"Cómo aprende una red neuronal","start":421.20000000000005},{"title":"En el caso de la informalidad laboral","start":530.4360000000001}],"scenes":[{"id":"gancho","start":0,"end":11.783999999999999},{"id":"funcion","start":11.783999999999999,"end":28.772},{"id":"inteligencia","start":28.772,"end":50.385999999999996},{"id":"niveles","start":50.385999999999996,"end":86.162},{"id":"entrenar","start":86.162,"end":105.64600000000002},{"id":"regresion","start":105.64600000000002,"end":142.16000000000003},{"id":"linea","start":142.16000000000003,"end":179.47200000000004},{"id":"motores","start":179.47200000000004,"end":203.66000000000003},{"id":"eliza","start":203.66000000000003,"end":241.628},{"id":"tres-epocas","start":241.628,"end":252.54799999999997},{"id":"pesos","start":258.548,"end":285.52000000000004},{"id":"categorias","start":285.52000000000004,"end":321.03200000000004},{"id":"latam","start":321.03200000000004,"end":353.91600000000005},{"id":"ranking","start":353.91600000000005,"end":388.34800000000007},{"id":"eleccion","start":388.34800000000007,"end":415.20000000000005},{"id":"neurona","start":421.20000000000005,"end":450.6160000000001},{"id":"montana","start":450.6160000000001,"end":474.25200000000007},{"id":"sobreajuste","start":474.25200000000007,"end":500.3920000000001},{"id":"caja-negra","start":500.3920000000001,"end":524.4360000000001},{"id":"caso","start":530.4360000000001,"end":573.1260000000002},{"id":"cierre","start":573.1260000000002,"end":586.8540000000003}],"lines":[{"scene":"gancho","index":0,"voice":"narrador","start":0,"dur":9.984,"chunks":[{"text":"¿Para qué usa hoy la IA en su investigación?","start":0,"end":3.418375},{"text":"Antes de responder, conviene saber qué es ese instrumento,","start":3.418375,"end":7.104583},{"text":"cómo se construyó y qué puede medir.","start":7.104583,"end":9.984}]},{"scene":"funcion","index":0,"voice":"narrador","start":0,"dur":8.376,"chunks":[{"text":"Según el programa del curso, un modelo de IA es una función ajustada a datos:","start":0,"end":5.01175},{"text":"recibe una entrada y produce una salida.","start":5.01175,"end":8.376}]},{"scene":"funcion","index":1,"voice":"narrador","start":0,"dur":6.312,"chunks":[{"text":"Los parámetros del modelo se ajustaron para","start":0,"end":2.358666},{"text":"que el error en ejemplos conocidos fuera el menor posible.","start":2.358666,"end":6.312}]},{"scene":"inteligencia","index":0,"voice":"mariana","start":0,"dur":4.32,"chunks":[{"text":"Si responde tan bien, es porque entiende lo que le pregunto.","start":0,"end":4.32}]},{"scene":"inteligencia","index":1,"voice":"narrador","start":0,"dur":15.144,"chunks":[{"text":"La palabra «inteligencia» puede engañar.","start":0,"end":3.176},{"text":"Estos sistemas detectan regularidades estadísticas en enormes cantidades de datos","start":3.176,"end":7.857125},{"text":"y las usan para predecir.","start":7.857125,"end":10.216833},{"text":"Responder bien no significa entender el mundo que describen esos datos.","start":10.216833,"end":15.144}]},{"scene":"niveles","index":0,"voice":"narrador","start":0,"dur":11.712,"chunks":[{"text":"Piense en cuatro niveles, uno dentro de otro.","start":0,"end":3.686208},{"text":"La inteligencia artificial incluye sistemas de reglas escritas a mano, como ELIZA,","start":3.686208,"end":8.915833},{"text":"y sistemas que aprenden de datos.","start":8.915833,"end":11.712}]},{"scene":"niveles","index":1,"voice":"narrador","start":0,"dur":8.784,"chunks":[{"text":"El aprendizaje automático extrae patrones de los ejemplos,","start":0,"end":3.697958},{"text":"y el aprendizaje profundo lo hace con redes neuronales de muchas capas.","start":3.697958,"end":8.784}]},{"scene":"niveles","index":2,"voice":"narrador","start":0,"dur":12.48,"chunks":[{"text":"La IA generativa produce contenido nuevo; un LLM es IA generativa para texto.","start":0,"end":6.568875},{"text":"Todo LLM es aprendizaje profundo, pero no toda la IA aprende de datos.","start":6.568875,"end":12.48}]},{"scene":"entrenar","index":0,"voice":"narrador","start":0,"dur":9.936,"chunks":[{"text":"Entrenar es ajustar los parámetros con datos, algo costoso que se hace pocas veces;","start":0,"end":5.317875},{"text":"inferir es usar el modelo ya entrenado, como ocurre en un chat.","start":5.317875,"end":9.936}]},{"scene":"entrenar","index":1,"voice":"narrador","start":0,"dur":7.248,"chunks":[{"text":"Los parámetros son las perillas que ajusta el entrenamiento:","start":0,"end":3.391833},{"text":"los LLM actuales tienen miles de millones.","start":3.391833,"end":7.248}]},{"scene":"regresion","index":0,"voice":"julian","start":0,"dur":7.2,"chunks":[{"text":"Para un economista, la idea es conocida:","start":0,"end":2.715833},{"text":"una regresión lineal es un modelo con pocos parámetros ajustados a datos.","start":2.715833,"end":7.2}]},{"scene":"regresion","index":1,"voice":"narrador","start":0,"dur":14.832,"chunks":[{"text":"Un LLM aplica la misma idea con miles de millones de parámetros.","start":0,"end":5.229583},{"text":"Según Mullainathan y Spiess, la econometría suele estimar e interpretar un efecto,","start":5.229583,"end":10.293375},{"text":"y el aprendizaje automático, predecir bien casos nuevos.","start":10.293375,"end":14.832}]},{"scene":"regresion","index":2,"voice":"narrador","start":0,"dur":11.832,"chunks":[{"text":"Por eso, para la validez, predecir bien no es lo mismo que identificar efectos:","start":0,"end":5.330625},{"text":"según Athey e Imbens,","start":5.330625,"end":6.976},{"text":"las preguntas causales siguen necesitando diseños de identificación.","start":6.976,"end":11.832}]},{"scene":"linea","index":0,"voice":"narrador","start":0,"dur":17.472,"chunks":[{"text":"La historia de la IA alterna promesas y decepciones.","start":0,"end":4.056125},{"text":"En 1950, Turing propuso el juego de la imitación;","start":4.056125,"end":8.252541},{"text":"en 1956 nació el término «inteligencia artificial»; en 1958,","start":8.252541,"end":14.502541},{"text":"el perceptrón aprendió de ejemplos.","start":14.502541,"end":17.472}]},{"scene":"linea","index":1,"voice":"narrador","start":0,"dur":9.216,"chunks":[{"text":"Los inviernos de las décadas de 1970 y 1980 llegaron","start":0,"end":4.667333},{"text":"cuando las expectativas superaron lo que la técnica podía cumplir.","start":4.667333,"end":9.216}]},{"scene":"linea","index":2,"voice":"narrador","start":0,"dur":7.824,"chunks":[{"text":"La idea de red neuronal existía desde 1958:","start":0,"end":4.322958},{"text":"lo que cambió después de 2012 fue la escala.","start":4.322958,"end":7.824}]},{"scene":"motores","index":0,"voice":"narrador","start":0,"dur":12.696,"chunks":[{"text":"Crecieron a la vez tres motores: datos digitales masivos; procesadores gráficos,","start":0,"end":5.547458},{"text":"que hacen millones de cálculos en paralelo; y mejores algoritmos,","start":5.547458,"end":9.527041},{"text":"como el Transformer de 2017.","start":9.527041,"end":12.696}]},{"scene":"motores","index":1,"voice":"narrador","start":0,"dur":9.192,"chunks":[{"text":"Y desde ChatGPT, en 2022, la IA dejó de ser una herramienta de especialistas:","start":0,"end":6.121416},{"text":"hoy aparece en todas las disciplinas.","start":6.121416,"end":9.192}]},{"scene":"eliza","index":0,"voice":"narrador","start":0,"dur":12.408,"chunks":[{"text":"La demostración del curso hace la misma pregunta a tres épocas.","start":0,"end":4.604583},{"text":"ELIZA, de 1966,","start":4.604583,"end":7.436208},{"text":"usa reglas simples que imitan a un terapeuta y solo responde en inglés.","start":7.436208,"end":12.408}]},{"scene":"eliza","index":1,"voice":"narrador","start":0,"dur":9.096,"chunks":[{"text":"En una prueba, ante la pregunta por las causas del empleo informal,","start":0,"end":4.055083},{"text":"respondió con otra pregunta: «¿En qué le ayudaría una respuesta a eso?».","start":4.055083,"end":9.096}]},{"scene":"eliza","index":2,"voice":"mariana","start":0,"dur":4.296,"chunks":[{"text":"Y el chat actual me respondió con fluidez y en español.","start":0,"end":4.296}]},{"scene":"eliza","index":3,"voice":"narrador","start":0,"dur":9.168,"chunks":[{"text":"La fluidez no es veracidad.","start":0,"end":2.780625},{"text":"Weizenbaum se alarmó de que la gente le atribuyera comprensión a su programa:","start":2.780625,"end":7.117333},{"text":"es el efecto ELIZA.","start":7.117333,"end":9.168}]},{"scene":"tres-epocas","index":0,"voice":"narrador","start":0,"dur":9.12,"chunks":[{"text":"Compare las tres respuestas: ¿qué cambió de una época a otra?","start":0,"end":4.808666},{"text":"Piénselo, o converse con su grupo, antes de seguir.","start":4.808666,"end":9.12}]},{"scene":"pesos","index":0,"voice":"narrador","start":0,"dur":12.312,"chunks":[{"text":"Cambiaron el tamaño, los datos y el ajuste para seguir instrucciones.","start":0,"end":5.140291},{"text":"Y como los modelos se actualizan y se retiran en cuestión de meses,","start":5.140291,"end":8.78825},{"text":"registre siempre nombre, versión y fecha.","start":8.78825,"end":12.312}]},{"scene":"pesos","index":1,"voice":"narrador","start":0,"dur":12.36,"chunks":[{"text":"Un modelo entrenado es, en el fondo, un archivo enorme de números: los pesos.","start":0,"end":6.096958},{"text":"Lo que una empresa publica de ese archivo, y de cómo lo produjo,","start":6.096958,"end":9.910708},{"text":"define tres categorías.","start":9.910708,"end":12.36}]},{"scene":"categorias","index":0,"voice":"narrador","start":0,"dur":11.28,"chunks":[{"text":"De código abierto: se publican los pesos,","start":0,"end":2.958166},{"text":"el código de entrenamiento","start":2.958166,"end":4.361208},{"text":"e información suficiente sobre los datos para reconstruir el modelo,","start":4.361208,"end":8.340833},{"text":"según la definición de la OSI.","start":8.340833,"end":11.28}]},{"scene":"categorias","index":1,"voice":"narrador","start":0,"dur":10.464,"chunks":[{"text":"De pesos abiertos: solo se publican los pesos,","start":0,"end":3.21325},{"text":"con licencias que van de muy libres a restrictivas;","start":3.21325,"end":6.223458},{"text":"el modelo puede correr sin internet y con una versión fija.","start":6.223458,"end":10.464}]},{"scene":"categorias","index":2,"voice":"narrador","start":0,"dur":10.968,"chunks":[{"text":"Cerrados: el acceso es solo por app o API.","start":0,"end":4.056125},{"text":"Suelen liderar en capacidad, pero cambian o se retiran sin aviso,","start":4.056125,"end":8.13775},{"text":"y los datos salen de su computador.","start":8.13775,"end":10.968}]},{"scene":"latam","index":0,"voice":"narrador","start":0,"dur":10.008,"chunks":[{"text":"Un caso para discutir: Latam-GPT,","start":0,"end":2.996416},{"text":"lanzado en febrero de 2026","start":2.996416,"end":5.101},{"text":"y coordinado por el CENIA de Chile con instituciones de 15 países.","start":5.101,"end":10.008}]},{"scene":"latam","index":1,"voice":"mariana","start":0,"dur":4.032,"chunks":[{"text":"Se presenta como de código abierto, así que lo es.","start":0,"end":4.032}]},{"scene":"latam","index":2,"voice":"narrador","start":0,"dur":16.344,"chunks":[{"text":"No.","start":0,"end":1.377541},{"text":"El modelo publicado es Llama 3.1 70B reentrenado con un corpus latinoamericano","start":1.377541,"end":6.9005},{"text":"y conserva la licencia de Llama.","start":6.9005,"end":9.591833},{"text":"Según la OSI, es de pesos abiertos:","start":9.591833,"end":12.602041},{"text":"pesos abiertos no es lo mismo que código abierto.","start":12.602041,"end":16.344}]},{"scene":"ranking","index":0,"voice":"narrador","start":0,"dur":15.96,"chunks":[{"text":"Artificial Analysis compara modelos con un índice de inteligencia.","start":0,"end":4.923458},{"text":"En su foto del 22 de octubre de 2026,","start":4.923458,"end":8.16325},{"text":"el mejor cerrado obtenía 58 y el mejor de pesos abiertos, 46:","start":8.16325,"end":13.571416},{"text":"12 puntos de diferencia.","start":13.571416,"end":15.96}]},{"scene":"ranking","index":1,"voice":"narrador","start":0,"dur":10.896,"chunks":[{"text":"Pero ese índice promedia diez evaluaciones, casi todas en inglés:","start":0,"end":4.348458},{"text":"el desempeño en español no aparece ahí.","start":4.348458,"end":7.627541},{"text":"Pruebe con una muestra de su propio material.","start":7.627541,"end":10.896}]},{"scene":"ranking","index":2,"voice":"narrador","start":0,"dur":4.776,"chunks":[{"text":"Y como el ranking cambia cada semana, en clase se abre en vivo.","start":0,"end":4.776}]},{"scene":"eleccion","index":0,"voice":"narrador","start":0,"dur":13.104,"chunks":[{"text":"Elegir modelo es una decisión metodológica, como elegir un programa estadístico:","start":0,"end":5.126541},{"text":"en la sección de métodos se justifica cuál, qué versión,","start":5.126541,"end":8.519375},{"text":"con qué configuración y en qué fecha, y se confirma la licencia.","start":8.519375,"end":13.104}]},{"scene":"eleccion","index":1,"voice":"narrador","start":0,"dur":11.448,"chunks":[{"text":"Un modelo de pesos abiertos puede correr en su computador sin enviar datos a nadie;","start":0,"end":4.935208},{"text":"con uno cerrado, el material viaja a servidores de la empresa,","start":4.935208,"end":8.902041},{"text":"casi siempre en el exterior.","start":8.902041,"end":11.448}]},{"scene":"neurona","index":0,"voice":"narrador","start":0,"dur":9.552,"chunks":[{"text":"Una neurona artificial recibe varios números,","start":0,"end":3.047458},{"text":"multiplica cada uno por un peso que indica su importancia,","start":3.047458,"end":6.682666},{"text":"los suma y calcula cuánto se activa.","start":6.682666,"end":9.552}]},{"scene":"neurona","index":1,"voice":"narrador","start":0,"dur":5.208,"chunks":[{"text":"Una sola neurona de este tipo se parece mucho a una regresión logística.","start":0,"end":5.208}]},{"scene":"neurona","index":2,"voice":"narrador","start":0,"dur":11.856,"chunks":[{"text":"Una red apila capas de neuronas:","start":0,"end":2.307666},{"text":"las primeras detectan patrones simples y las siguientes los combinan.","start":2.307666,"end":6.824},{"text":"En imágenes, primero bordes, luego formas y luego objetos.","start":6.824,"end":11.856}]},{"scene":"montana","index":0,"voice":"narrador","start":0,"dur":11.52,"chunks":[{"text":"Aprender es ajustar pesos: la red predice,","start":0,"end":3.226},{"text":"se mide el error y cada peso se mueve un poco en la dirección que reduce ese error.","start":3.226,"end":8.571416},{"text":"Esto se repite millones de veces.","start":8.571416,"end":11.52}]},{"scene":"montana","index":1,"voice":"narrador","start":0,"dur":9.816,"chunks":[{"text":"Es como bajar una montaña con niebla, tanteando la pendiente bajo los pies.","start":0,"end":5.357125},{"text":"La retropropagación reparte la culpa del error entre los pesos.","start":5.357125,"end":9.816}]},{"scene":"sobreajuste","index":0,"voice":"narrador","start":0,"dur":11.88,"chunks":[{"text":"Generalizar, no memorizar: una red que memoriza sus ejemplos falla con casos nuevos.","start":0,"end":6.301},{"text":"Es el sobreajuste, como el estudiante que solo memorizó el examen del año pasado.","start":6.301,"end":11.88}]},{"scene":"sobreajuste","index":1,"voice":"julian","start":0,"dur":6.024,"chunks":[{"text":"Es el mismo riesgo de un modelo econométrico con demasiadas variables:","start":0,"end":3.876541},{"text":"el modelo aprende el ruido.","start":3.876541,"end":6.024}]},{"scene":"sobreajuste","index":2,"voice":"narrador","start":0,"dur":5.736,"chunks":[{"text":"Por eso todo modelo predictivo se evalúa con datos","start":0,"end":2.958166},{"text":"que no vio durante el entrenamiento.","start":2.958166,"end":5.736}]},{"scene":"caja-negra","index":0,"voice":"narrador","start":0,"dur":10.872,"chunks":[{"text":"¿Por qué se le llama caja negra?","start":0,"end":2.589291},{"text":"El modelo tiene millones de parámetros, y ninguno tiene un significado aislado,","start":2.589291,"end":7.5},{"text":"como sí lo tiene un coeficiente de regresión.","start":7.5,"end":10.872}]},{"scene":"caja-negra","index":1,"voice":"narrador","start":0,"dur":10.872,"chunks":[{"text":"Cuando la explicación importa,","start":0,"end":1.988791},{"text":"por ejemplo en decisiones de política pública sobre personas, se exigen auditorías,","start":1.988791,"end":7.180083},{"text":"métodos de explicabilidad o modelos más simples.","start":7.180083,"end":10.872}]},{"scene":"caso","index":0,"voice":"amparo","start":0,"dur":10.728,"chunks":[{"text":"Nuestro proyecto es el caso del curso: informalidad laboral en Colombia,","start":0,"end":4.501541},{"text":"con literatura de economía y sociología,","start":4.501541,"end":7.129083},{"text":"datos públicos del DANE y material cualitativo.","start":7.129083,"end":10.728}]},{"scene":"caso","index":1,"voice":"julian","start":0,"dur":6.384,"chunks":[{"text":"En datos va la Gran Encuesta Integrada de Hogares, y para practicar,","start":0,"end":3.863791},{"text":"solo entrevistas sintéticas.","start":3.863791,"end":6.384}]},{"scene":"caso","index":2,"voice":"mariana","start":0,"dur":11.016,"chunks":[{"text":"Tres tareas para la IA: buscar literatura,","start":0,"end":3.4375},{"text":"organizar los PDF y hacer una primera codificación.","start":3.4375,"end":7.45},{"text":"Y un riesgo: que invente referencias.","start":7.45,"end":11.016}]},{"scene":"caso","index":3,"voice":"narrador","start":0,"dur":11.712,"chunks":[{"text":"Los productos de esta sesión son esa ficha y la primera entrada de la bitácora,","start":0,"end":4.552541},{"text":"con fecha, herramienta y versión, tarea, instrucción, resultado,","start":4.552541,"end":9.38675},{"text":"verificación y decisión.","start":9.38675,"end":11.712}]},{"scene":"cierre","index":0,"voice":"narrador","start":0,"dur":11.928,"chunks":[{"text":"La idea de esta sesión: las salidas de un modelo son estimaciones con error,","start":0,"end":4.782125},{"text":"no hechos.","start":4.782125,"end":6.415833},{"text":"Trátelas como las mediciones de un instrumento nuevo: compruébelas en una muestra.","start":6.415833,"end":11.928}]}],"checkpoints":[],"pauses":[{"after":"tres-epocas","start":252.54799999999997,"end":258.548},{"after":"eleccion","start":415.20000000000005,"end":421.20000000000005},{"after":"caja-negra","start":524.4360000000001,"end":530.4360000000001}]},"v2":{"file":"v2.mp3","duration":586.4360000000003,"chapters":[{"title":"Predecir el siguiente token","start":0},{"title":"Tokens: la unidad de costo y de límite","start":137.46599999999998},{"title":"Embeddings: un mapa de significados","start":231.7939999999999},{"title":"Atención y dos familias de modelos","start":336.74999999999994},{"title":"Instrucciones: seis partes y un bucle","start":443.56200000000007},{"title":"En el caso de la informalidad laboral","start":529.7300000000001}],"scenes":[{"id":"gancho","start":0,"end":13.031999999999998},{"id":"por-que-texto","start":13.031999999999998,"end":36.62},{"id":"ciclo","start":36.62,"end":63.06},{"id":"fases","start":63.06,"end":85.23200000000001},{"id":"plausible","start":85.23200000000001,"end":105.982},{"id":"deriva","start":105.982,"end":137.46599999999998},{"id":"tokens","start":137.46599999999998,"end":154.45399999999998},{"id":"limites","start":154.45399999999998,"end":177.36999999999995},{"id":"espanol","start":177.36999999999995,"end":200.9579999999999},{"id":"largo","start":200.9579999999999,"end":231.7939999999999},{"id":"mapa","start":231.7939999999999,"end":256.7979999999999},{"id":"municipios","start":256.7979999999999,"end":281.2259999999999},{"id":"usos-emb","start":281.2259999999999,"end":313.5699999999999},{"id":"similar","start":313.5699999999999,"end":336.74999999999994},{"id":"banco","start":336.74999999999994,"end":358.58599999999996},{"id":"pesos-espaciales","start":358.58599999999996,"end":377.536},{"id":"familias","start":377.536,"end":413.624},{"id":"mapas-atencion","start":413.624,"end":443.56200000000007},{"id":"seis-partes","start":443.56200000000007,"end":468.6380000000001},{"id":"bucle","start":468.6380000000001,"end":490.66600000000005},{"id":"metodo","start":490.66600000000005,"end":523.7300000000001},{"id":"caso","start":529.7300000000001,"end":564.4760000000002},{"id":"cierre","start":570.4760000000002,"end":586.4360000000003}],"lines":[{"scene":"gancho","index":0,"voice":"narrador","start":0,"dur":11.232,"chunks":[{"text":"Escriba «The capital of Colombia is» y pregúntese qué palabra sigue.","start":0,"end":4.757666},{"text":"Un LLM hace algo parecido, token por token, una y otra vez: así escribe.","start":4.757666,"end":11.232}]},{"scene":"por-que-texto","index":0,"voice":"narrador","start":0,"dur":14.52,"chunks":[{"text":"Buena parte del conocimiento humano ya está escrito: libros, artículos, leyes,","start":0,"end":5.624},{"text":"foros.","start":5.624,"end":7.040833},{"text":"Ese texto trae su propia respuesta correcta:","start":7.040833,"end":10.01275},{"text":"basta tapar la palabra siguiente y pedirle al modelo que la prediga.","start":10.01275,"end":14.52}]},{"scene":"por-que-texto","index":1,"voice":"narrador","start":0,"dur":6.768,"chunks":[{"text":"Así se entrena con billones de palabras sin etiquetarlas a mano:","start":0,"end":3.8255},{"text":"es el aprendizaje autosupervisado.","start":3.8255,"end":6.768}]},{"scene":"ciclo","index":0,"voice":"narrador","start":0,"dur":6.96,"chunks":[{"text":"El ciclo completo: el texto se corta en tokens,","start":0,"end":3.506625},{"text":"y cada token se vuelve una lista de números.","start":3.506625,"end":6.96}]},{"scene":"ciclo","index":1,"voice":"narrador","start":0,"dur":5.4,"chunks":[{"text":"Las capas de atención ajustan el significado de cada token según el contexto.","start":0,"end":5.4}]},{"scene":"ciclo","index":2,"voice":"narrador","start":0,"dur":11.28,"chunks":[{"text":"El modelo calcula qué tan probable es cada fragmento siguiente, elige uno,","start":0,"end":4.833166},{"text":"lo agrega al texto y repite.","start":4.833166,"end":7.346958},{"text":"La temperatura controla cuánto azar hay en esa elección.","start":7.346958,"end":11.28}]},{"scene":"fases","index":0,"voice":"narrador","start":0,"dur":8.136,"chunks":[{"text":"Primero, el preentrenamiento produce un modelo base que solo continúa texto,","start":0,"end":4.999},{"text":"como el GPT-2 de la primera sesión.","start":4.999,"end":8.136}]},{"scene":"fases","index":1,"voice":"narrador","start":0,"dur":11.736,"chunks":[{"text":"Después,","start":0,"end":0.993875},{"text":"el ajuste con instrucciones y con preferencias humanas lo convierte en asistente;","start":0.993875,"end":5.598458},{"text":"los modelos de razonamiento, además, generan pasos intermedios antes de responder.","start":5.598458,"end":11.736}]},{"scene":"plausible","index":0,"voice":"mariana","start":0,"dur":5.496,"chunks":[{"text":"Si me lo dice con tanta seguridad, debe haberlo sacado de alguna base de datos.","start":0,"end":5.496}]},{"scene":"plausible","index":1,"voice":"narrador","start":0,"dur":13.104,"chunks":[{"text":"No: el modelo no consulta una base de hechos,","start":0,"end":3.315291},{"text":"salvo que la herramienta busque en la web o en sus documentos.","start":3.315291,"end":7.48725},{"text":"Produce lo probable, no lo verificado: por eso es fluido y a veces inventa.","start":7.48725,"end":13.104}]},{"scene":"deriva","index":0,"voice":"narrador","start":0,"dur":15.288,"chunks":[{"text":"El mismo servicio cambia con el tiempo.","start":0,"end":3.188791},{"text":"Según Chen, Zaharia y Zou,","start":3.188791,"end":5.561208},{"text":"en 2023 GPT-4 pasó de 84 % a 51 % de aciertos al identificar números primos,","start":5.561208,"end":13.188791},{"text":"entre marzo y junio.","start":13.188791,"end":15.288}]},{"scene":"deriva","index":1,"voice":"narrador","start":0,"dur":13.896,"chunks":[{"text":"Registre fecha y versión, y vuelva a validar cuando cambie el modelo.","start":0,"end":4.897958},{"text":"Además, con una temperatura mayor que cero,","start":4.897958,"end":7.933666},{"text":"la misma instrucción da respuestas distintas:","start":7.933666,"end":10.535708},{"text":"repita la tarea y reporte cuánto varían.","start":10.535708,"end":13.896}]},{"scene":"tokens","index":0,"voice":"narrador","start":0,"dur":6.96,"chunks":[{"text":"Los tokens son fragmentos de texto: palabras frecuentes enteras,","start":0,"end":4.361208},{"text":"partes de palabras o signos.","start":4.361208,"end":6.96}]},{"scene":"tokens","index":1,"voice":"narrador","start":0,"dur":7.728,"chunks":[{"text":"Según OpenAI, en inglés un token equivale a unos 4 caracteres,","start":0,"end":4.909708},{"text":"cerca de tres cuartos de palabra.","start":4.909708,"end":7.728}]},{"scene":"limites","index":0,"voice":"narrador","start":0,"dur":10.44,"chunks":[{"text":"Los límites de uso, los precios y la ventana de contexto se miden en tokens.","start":0,"end":5.854583},{"text":"La ventana de contexto es cuánto texto procesa el modelo a la vez.","start":5.854583,"end":10.44}]},{"scene":"limites","index":1,"voice":"narrador","start":0,"dur":10.176,"chunks":[{"text":"Las imágenes y el audio también se cortan en tokens:","start":0,"end":3.391833},{"text":"así un mismo modelo procesa texto, imagen y sonido.","start":3.391833,"end":7.729583},{"text":"Eso es la multimodalidad.","start":7.729583,"end":10.176}]},{"scene":"espanol","index":0,"voice":"narrador","start":0,"dur":13.2,"chunks":[{"text":"Ahora, la equidad.","start":0,"end":2.46175},{"text":"Según Petrov y coautores,","start":2.46175,"end":4.375},{"text":"el mismo texto necesita 1,55 veces más tokens en español que en inglés,","start":4.375,"end":10.242333},{"text":"con el tokenizador de GPT-4.","start":10.242333,"end":13.2}]},{"scene":"espanol","index":1,"voice":"narrador","start":0,"dur":8.088,"chunks":[{"text":"Trabajar en español cuesta más,","start":0,"end":2.167333},{"text":"agota antes los límites de uso y deja menos espacio útil en la ventana de contexto.","start":2.167333,"end":8.088}]},{"scene":"largo","index":0,"voice":"narrador","start":0,"dur":11.088,"chunks":[{"text":"Con documentos largos, según Liu y coautores,","start":0,"end":3.21325},{"text":"el modelo puede atender peor lo que está en la mitad del texto:","start":3.21325,"end":6.822958},{"text":"divida el material y pida citas textuales con su ubicación.","start":6.822958,"end":11.088}]},{"scene":"largo","index":1,"voice":"narrador","start":0,"dur":17.448,"chunks":[{"text":"Y como el modelo procesa fragmentos, no letras,","start":0,"end":3.328041},{"text":"no le pida contar palabras ni calcular frecuencias exactas:","start":3.328041,"end":6.976},{"text":"pídale que escriba y ejecute código,","start":6.976,"end":9.322958},{"text":"o haga usted el conteo en un programa estadístico.","start":9.322958,"end":12.844375},{"text":"Los tokens explican costos, límites y algunos errores.","start":12.844375,"end":17.448}]},{"scene":"mapa","index":0,"voice":"narrador","start":0,"dur":10.776,"chunks":[{"text":"Un embedding representa cada token,","start":0,"end":2.345916},{"text":"frase o documento como una lista de cientos o miles de números:","start":2.345916,"end":6.210708},{"text":"un punto en un mapa de significados donde lo parecido queda cerca.","start":6.210708,"end":10.776}]},{"scene":"mapa","index":1,"voice":"narrador","start":0,"dur":11.928,"chunks":[{"text":"Las direcciones también significan algo:","start":0,"end":2.652041},{"text":"si a «rey» se le quita lo de «hombre» y se le suma lo de «mujer»,","start":2.652041,"end":5.891833},{"text":"se llega cerca de «reina».","start":5.891833,"end":8.214291},{"text":"Así lo mostró word2vec, en 2013.","start":8.214291,"end":11.928}]},{"scene":"municipios","index":0,"voice":"narrador","start":0,"dur":8.304,"chunks":[{"text":"Así como un municipio se ubica con latitud y longitud,","start":0,"end":3.506625},{"text":"un embedding ubica significados en un espacio de muchas dimensiones.","start":3.506625,"end":8.304}]},{"scene":"municipios","index":1,"voice":"narrador","start":0,"dur":13.824,"chunks":[{"text":"El paralelo existe literalmente: según Google DeepMind,","start":0,"end":3.953041},{"text":"AlphaEarth Foundations resume datos ópticos, de radar,","start":3.953041,"end":7.626541},{"text":"de clima y otros en 64 números por cada cuadro de 10 por 10 metros del planeta.","start":7.626541,"end":13.824}]},{"scene":"usos-emb","index":0,"voice":"narrador","start":0,"dur":9.84,"chunks":[{"text":"Los embeddings sirven para buscar por significado,","start":0,"end":3.085708},{"text":"agrupar respuestas abiertas de encuestas,","start":3.085708,"end":5.611208},{"text":"detectar temas o comparar documentos de política pública.","start":5.611208,"end":9.84}]},{"scene":"usos-emb","index":1,"voice":"narrador","start":0,"dur":10.176,"chunks":[{"text":"Y son un instrumento de medición: con ellos,","start":0,"end":3.009166},{"text":"Garg y coautores midieron la evolución de los estereotipos de género","start":3.009166,"end":6.618875},{"text":"y etnia en EE. UU. durante 100 años.","start":6.618875,"end":10.176}]},{"scene":"usos-emb","index":2,"voice":"narrador","start":0,"dur":9.528,"chunks":[{"text":"Pero, según Caliskan y coautores, también reproducen asociaciones sesgadas:","start":0,"end":4.973458},{"text":"si los usa para buscar o clasificar, puede heredar esos sesgos.","start":4.973458,"end":9.528}]},{"scene":"similar","index":0,"voice":"narrador","start":0,"dur":11.136,"chunks":[{"text":"Dos cuidados.","start":0,"end":1.964291},{"text":"La búsqueda por significado encuentra lo parecido,","start":1.964291,"end":4.949},{"text":"no todo lo que cumple un criterio:","start":4.949,"end":6.977041},{"text":"no reemplaza una búsqueda sistemática con palabras clave.","start":6.977041,"end":11.136}]},{"scene":"similar","index":1,"voice":"narrador","start":0,"dur":9.744,"chunks":[{"text":"Y al evaluar un modelo espacial, separe zonas de entrenamiento y de prueba:","start":0,"end":4.552541},{"text":"las zonas vecinas se parecen y, si se mezclan, el desempeño se infla.","start":4.552541,"end":9.744}]},{"scene":"banco","index":0,"voice":"narrador","start":0,"dur":13.056,"chunks":[{"text":"El significado depende del contexto.","start":0,"end":3.188791},{"text":"«Me senté en el banco del parque».","start":3.188791,"end":5.867333},{"text":"«El banco subió la tasa de interés».","start":5.867333,"end":8.826541},{"text":"La palabra «banco» no significa lo mismo en las dos frases.","start":8.826541,"end":13.056}]},{"scene":"banco","index":1,"voice":"narrador","start":0,"dur":6.48,"chunks":[{"text":"Con la atención,","start":0,"end":1.249},{"text":"cada token pondera a los demás para ajustar su significado según el contexto.","start":1.249,"end":6.48}]},{"scene":"pesos-espaciales","index":0,"voice":"julian","start":0,"dur":7.992,"chunks":[{"text":"Para un economista, se parece a una matriz de pesos espaciales,","start":0,"end":3.914791},{"text":"pero calculada a partir del contexto y distinta para cada frase.","start":3.914791,"end":7.992}]},{"scene":"pesos-espaciales","index":1,"voice":"narrador","start":0,"dur":8.808,"chunks":[{"text":"El Transformer, de 2017, apila decenas de capas de atención:","start":0,"end":5.101},{"text":"es la base de todos los LLM actuales.","start":5.101,"end":8.808}]},{"scene":"familias","index":0,"voice":"narrador","start":0,"dur":13.512,"chunks":[{"text":"Hay dos familias.","start":0,"end":2.130083},{"text":"Los codificadores, tipo BERT,","start":2.130083,"end":4.426},{"text":"leen toda la frase en ambas direcciones y sirven para analizar y clasificar texto;","start":4.426,"end":9.33675},{"text":"en español existe BETO, de la Universidad de Chile.","start":9.33675,"end":13.512}]},{"scene":"familias","index":1,"voice":"narrador","start":0,"dur":9.552,"chunks":[{"text":"Los decodificadores, tipo GPT, leen de izquierda a derecha y generan texto:","start":0,"end":5.483666},{"text":"a esa familia pertenecen todos los chats actuales.","start":5.483666,"end":9.552}]},{"scene":"familias","index":2,"voice":"narrador","start":0,"dur":10.224,"chunks":[{"text":"Para clasificar miles de textos,","start":0,"end":2.333166},{"text":"un modelo pequeño tipo BERT ajustado con ejemplos etiquetados suele ser más barato,","start":2.333166,"end":7.307666},{"text":"rápido y reproducible que un chat.","start":7.307666,"end":10.224}]},{"scene":"mapas-atencion","index":0,"voice":"mariana","start":0,"dur":4.728,"chunks":[{"text":"Entonces el mapa de atención me muestra por qué el modelo clasificó así.","start":0,"end":4.728}]},{"scene":"mapas-atencion","index":1,"voice":"narrador","start":0,"dur":13.872,"chunks":[{"text":"No.","start":0,"end":1.377541},{"text":"Según Jain y Wallace,","start":1.377541,"end":3.048458},{"text":"los mapas de atención muestran a qué tokens se dirige el cálculo,","start":3.048458,"end":6.734708},{"text":"pero no son una explicación confiable de por qué el modelo clasificó así:","start":6.734708,"end":10.867333},{"text":"no los presente como una explicación.","start":10.867333,"end":13.872}]},{"scene":"mapas-atencion","index":2,"voice":"narrador","start":0,"dur":8.688,"chunks":[{"text":"Lo que sí funciona es validar contra la codificación humana de una muestra","start":0,"end":3.965833},{"text":"y reportar el acuerdo,","start":3.965833,"end":5.407125},{"text":"con la kappa de Cohen o el alfa de Krippendorff.","start":5.407125,"end":8.688}]},{"scene":"seis-partes","index":0,"voice":"narrador","start":0,"dur":10.056,"chunks":[{"text":"Una buena instrucción tiene seis partes: contexto, tarea, insumos,","start":0,"end":5.0245},{"text":"criterios de calidad, formato de salida y una petición de honestidad.","start":5.0245,"end":10.056}]},{"scene":"seis-partes","index":1,"voice":"narrador","start":0,"dur":12.72,"chunks":[{"text":"La plantilla del curso termina con esta petición, dirigida al modelo:","start":0,"end":4.46325},{"text":"«Si algo no está en los insumos o no lo sabes, dilo. No inventes referencias; marca lo que debo verificar».","start":4.46325,"end":12.72}]},{"scene":"bucle","index":0,"voice":"narrador","start":0,"dur":11.448,"chunks":[{"text":"La instrucción se mejora en un bucle: escriba una primera versión,","start":0,"end":4.220916},{"text":"lea la respuesta como un revisor, diagnostique la causa de cada error,","start":4.220916,"end":8.468375},{"text":"ajuste solo eso y pruebe de nuevo.","start":8.468375,"end":11.448}]},{"scene":"bucle","index":1,"voice":"narrador","start":0,"dur":8.28,"chunks":[{"text":"Guarde la mejor versión en la bitácora y, si la tarea se repite,","start":0,"end":4.080625},{"text":"conviértala en una skill, como verá en la cuarta sesión.","start":4.080625,"end":8.28}]},{"scene":"metodo","index":0,"voice":"narrador","start":0,"dur":13.152,"chunks":[{"text":"La instrucción es parte del método.","start":0,"end":2.946416},{"text":"Según Sclar y coautores,","start":2.946416,"end":4.732125},{"text":"cambios de formato","start":4.732125,"end":5.701541},{"text":"que parecen triviales movieron el desempeño hasta 76 puntos de exactitud en un","start":5.701541,"end":10.625},{"text":"modelo de pesos abiertos.","start":10.625,"end":13.152}]},{"scene":"metodo","index":1,"voice":"narrador","start":0,"dur":7.776,"chunks":[{"text":"Publique la instrucción exacta, en el método o en un anexo,","start":0,"end":4.055083},{"text":"pruebe variantes y reporte el rango de resultados.","start":4.055083,"end":7.776}]},{"scene":"metodo","index":2,"voice":"narrador","start":0,"dur":9.336,"chunks":[{"text":"Y fíjela, con el libro de códigos, antes de ver los resultados finales:","start":0,"end":4.807666},{"text":"ajustarla hasta obtener lo esperado es una forma de manipularlos.","start":4.807666,"end":9.336}]},{"scene":"caso","index":0,"voice":"amparo","start":0,"dur":7.56,"chunks":[{"text":"Nuestra primera versión pide resumir artículos sobre salario mínimo e informalidad,","start":0,"end":4.680083},{"text":"en una tabla con método y hallazgo.","start":4.680083,"end":7.56}]},{"scene":"caso","index":1,"voice":"julian","start":0,"dur":5.496,"chunks":[{"text":"La probamos en dos chats cerrados y en uno de pesos abiertos, sin datos sensibles.","start":0,"end":5.496}]},{"scene":"caso","index":2,"voice":"mariana","start":0,"dur":9.936,"chunks":[{"text":"Leímos como revisores, buscando citas inventadas.","start":0,"end":4.6375},{"text":"En la segunda versión agregamos los PDF como insumos y la petición de honestidad.","start":4.6375,"end":9.936}]},{"scene":"caso","index":3,"voice":"narrador","start":0,"dur":8.904,"chunks":[{"text":"La tercera versión sale de los comentarios del grupo.","start":0,"end":3.903041},{"text":"Las tres versiones, con sus notas, son el producto de la sesión.","start":3.903041,"end":8.904}]},{"scene":"cierre","index":0,"voice":"narrador","start":0,"dur":14.16,"chunks":[{"text":"Quédese con esta idea: el modelo produce lo probable, no lo verificado.","start":0,"end":5.420916},{"text":"Con los modelos actuales, el material que usted entrega pesa más que la redacción:","start":5.420916,"end":10.395416},{"text":"usted elige las fuentes y comprueba cada respuesta.","start":10.395416,"end":14.16}]}],"checkpoints":[],"pauses":[{"after":"metodo","start":523.7300000000001,"end":529.7300000000001},{"after":"caso","start":564.4760000000002,"end":570.4760000000002}]},"v3":{"file":"v3.mp3","duration":697.7400000000004,"chapters":[{"title":"Ética y datos personales","start":0},{"title":"Avances con cifra y con límite","start":149.38799999999998},{"title":"Anotar, simular, citar","start":320.57199999999995},{"title":"El sesgo es un error sistemático","start":415.6619999999999},{"title":"Lo que el modelo calla","start":498.06199999999995},{"title":"Quién controla los recursos","start":572.488},{"title":"En el caso de la informalidad laboral","start":650.9840000000002}],"scenes":[{"id":"gancho","start":0,"end":11.111999999999998},{"id":"marcos","start":17.112,"end":53.92},{"id":"normas","start":53.92,"end":85.54800000000002},{"id":"privacidad","start":85.54800000000002,"end":104.052},{"id":"transferencia","start":104.052,"end":149.38799999999998},{"id":"avances","start":149.38799999999998,"end":182.98399999999998},{"id":"masai","start":182.98399999999998,"end":207.69999999999996},{"id":"educacion","start":207.69999999999996,"end":237.91199999999995},{"id":"trabajo","start":237.91199999999995,"end":271.6959999999999},{"id":"ciencia","start":271.6959999999999,"end":292.57199999999995},{"id":"pobreza","start":292.57199999999995,"end":320.57199999999995},{"id":"anotacion","start":320.57199999999995,"end":346.99199999999996},{"id":"silicio","start":346.99199999999996,"end":372.13399999999996},{"id":"referencias","start":372.13399999999996,"end":415.6619999999999},{"id":"sesgo","start":415.6619999999999,"end":454.078},{"id":"auditoria","start":454.078,"end":492.06199999999995},{"id":"abliterado","start":498.06199999999995,"end":524.89},{"id":"censura","start":524.89,"end":566.488},{"id":"recursos","start":572.488,"end":610.9320000000001},{"id":"region","start":610.9320000000001,"end":644.9840000000002},{"id":"caso","start":650.9840000000002,"end":676.2360000000003},{"id":"cierre","start":676.2360000000003,"end":691.7400000000004}],"lines":[{"scene":"gancho","index":0,"voice":"narrador","start":0,"dur":9.312,"chunks":[{"text":"¿La IA amplía o estrecha la ciencia?","start":0,"end":3.13775},{"text":"La sesión empieza con esa pregunta, en una escala de 1 a 5, y la repite al final.","start":3.13775,"end":9.312}]},{"scene":"marcos","index":0,"voice":"narrador","start":0,"dur":11.424,"chunks":[{"text":"La ética decide qué datos se pueden usar y con qué riesgos.","start":0,"end":4.324},{"text":"La Recomendación de la UNESCO, de 2021, la adoptaron los 193 Estados miembros.","start":4.324,"end":11.424}]},{"scene":"marcos","index":1,"voice":"narrador","start":0,"dur":12.792,"chunks":[{"text":"La evaluación de Colombia con la metodología RAM de la UNESCO señala brechas:","start":0,"end":4.590833},{"text":"el 13,8 % de las mujeres egresa de carreras STEM, frente al 35,1 % de los hombres.","start":4.590833,"end":12.792}]},{"scene":"marcos","index":2,"voice":"narrador","start":0,"dur":9.792,"chunks":[{"text":"También muestra una brecha de internet: 59,6 % en zonas rurales,","start":0,"end":5.547458},{"text":"frente a 82,6 % en zonas urbanas.","start":5.547458,"end":9.792}]},{"scene":"normas","index":0,"voice":"narrador","start":0,"dur":16.44,"chunks":[{"text":"Colombia tiene una política de IA, el CONPES 4144, con unos COP 479.000 millones.","start":0,"end":7.439329608938548},{"text":"A octubre de 2026 no tiene una ley general de IA:","start":7.439329608938548,"end":11.939664804469276},{"text":"el estado del proyecto de ley está en la tarjeta.","start":11.939664804469276,"end":16.44}]},{"scene":"normas","index":1,"voice":"narrador","start":0,"dur":12.888,"chunks":[{"text":"Y la Circular 002 de 2024 de la SIC exige evaluar el impacto en privacidad antes de","start":0,"end":5.845377049180327},{"text":"usar IA de alto riesgo,","start":5.845377049180327,"end":7.465180327868852},{"text":"y pedir consentimiento previo para usar datos personales tomados de internet.","start":7.465180327868852,"end":12.888}]},{"scene":"privacidad","index":0,"voice":"narrador","start":0,"dur":16.704,"chunks":[{"text":"En los planes personales, las conversaciones pueden usarse para entrenar modelos y,","start":0,"end":5.292333},{"text":"en algunos casos, las leen revisores humanos.","start":5.292333,"end":9.145416},{"text":"Revise la configuración de cada herramienta:","start":9.145416,"end":11.772958},{"text":"las condiciones de octubre de 2026 están en estas tarjetas.","start":11.772958,"end":16.704}]},{"scene":"transferencia","index":0,"voice":"mariana","start":0,"dur":7.824,"chunks":[{"text":"Si la SIC incluye a EE. UU. entre los países con nivel adecuado de protección,","start":0,"end":5.05},{"text":"puedo subir las entrevistas sin más.","start":5.05,"end":7.824}]},{"scene":"transferencia","index":1,"voice":"rojas","start":0,"dur":11.136,"chunks":[{"text":"No.","start":0,"end":0.20495705521472393},{"text":"Enviar datos personales a un proveedor en el exterior es una transferencia regulada","start":0.20495705521472393,"end":5.875435582822085},{"text":"por la Ley 1581,","start":5.875435582822085,"end":6.968539877300612},{"text":"y el nivel adecuado no reemplaza la autorización del titular.","start":6.968539877300612,"end":11.136}]},{"scene":"transferencia","index":2,"voice":"rojas","start":0,"dur":8.016,"chunks":[{"text":"Por eso el consentimiento informado debe mencionar la IA,","start":0,"end":3.051},{"text":"y el protocolo debe decir qué herramientas procesarán los datos y dónde se alojan.","start":3.051,"end":8.016}]},{"scene":"transferencia","index":3,"voice":"narrador","start":0,"dur":15.36,"chunks":[{"text":"Y no suba a una IA manuscritos ajenos para evaluarlos:","start":0,"end":3.608666},{"text":"eso viola la confidencialidad de la revisión por pares.","start":3.608666,"end":7.602041},{"text":"Los NIH de EE. UU. lo prohíben desde 2023,","start":7.602041,"end":11.670916},{"text":"y muchas revistas tienen políticas parecidas.","start":11.670916,"end":15.36}]},{"scene":"avances","index":0,"voice":"narrador","start":0,"dur":15.552,"chunks":[{"text":"La evidencia sobre la IA es desigual: lea cada avance con su cifra y con su límite.","start":0,"end":6.147958},{"text":"La base de datos de AlphaFold reúne más de 200 millones de estructuras de proteínas,","start":6.147958,"end":11.441333},{"text":"pero son predicciones: se validan con experimentos.","start":11.441333,"end":15.552}]},{"scene":"avances","index":1,"voice":"narrador","start":0,"dur":15.744,"chunks":[{"text":"En clima, según el artículo que lo presentó en 2023,","start":0,"end":4.220916},{"text":"GraphCast superó al mejor sistema de pronóstico operativo en el 90 % de 1.380","start":4.220916,"end":10.152041},{"text":"objetivos,","start":10.152041,"end":11.096958},{"text":"aunque las condiciones iniciales aún dependen de modelos físicos.","start":11.096958,"end":15.744}]},{"scene":"masai","index":0,"voice":"narrador","start":0,"dur":15.168,"chunks":[{"text":"En salud, el ensayo MASAI se hizo en Suecia con más de 100.000 mujeres.","start":0,"end":5.522958},{"text":"Con apoyo de IA se detectaron 29 % más cánceres,","start":5.522958,"end":9.41325},{"text":"la carga de lectura bajó 44 % y no hubo más falsos positivos.","start":9.41325,"end":15.168}]},{"scene":"masai","index":1,"voice":"narrador","start":0,"dur":7.248,"chunks":[{"text":"Sus límites: un país y un sistema,","start":0,"end":2.856125},{"text":"y la reducción de cánceres de intervalo no fue significativa.","start":2.856125,"end":7.248}]},{"scene":"educacion","index":0,"voice":"narrador","start":0,"dur":15.816,"chunks":[{"text":"En educación, una tutoría con GPT-4 después de clase, en Nigeria,","start":0,"end":5.05},{"text":"mejoró los resultados de aprendizaje en 0,31 desviaciones estándar en seis semanas,","start":5.05,"end":10.841833},{"text":"según un documento de trabajo del Banco Mundial sin revisión por pares.","start":10.841833,"end":15.816}]},{"scene":"educacion","index":1,"voice":"narrador","start":0,"dur":12.096,"chunks":[{"text":"Y en otro ensayo, publicado en PNAS,","start":0,"end":3.302541},{"text":"el acceso a GPT-4 sin guía dejó a los estudiantes 17 % por debajo del grupo de","start":3.302541,"end":8.965833},{"text":"control","start":8.965833,"end":9.4505},{"text":"cuando se retiró la herramienta.","start":9.4505,"end":12.096}]},{"scene":"trabajo","index":0,"voice":"narrador","start":0,"dur":7.008,"chunks":[{"text":"En el trabajo,","start":0,"end":1.210708},{"text":"el experimento de Noy y Zhang mostró 40 % menos tiempo en tareas de escritura.","start":1.210708,"end":7.008}]},{"scene":"trabajo","index":1,"voice":"narrador","start":0,"dur":10.992,"chunks":[{"text":"Y según Brynjolfsson y coautores,","start":0,"end":2.243875},{"text":"en atención al cliente se resolvieron de 14 a 15 % más casos por hora,","start":2.243875,"end":7.256625},{"text":"y 34 % más entre los novatos.","start":7.256625,"end":10.992}]},{"scene":"trabajo","index":2,"voice":"narrador","start":0,"dur":12.984,"chunks":[{"text":"Pero, según otro estudio, en tareas fuera de la frontera irregular de la IA,","start":0,"end":5.06275},{"text":"los consultores que la usaron acertaron 19 puntos menos:","start":5.06275,"end":8.889291},{"text":"pruebe la herramienta en su tarea concreta antes de adoptarla.","start":8.889291,"end":12.984}]},{"scene":"ciencia","index":0,"voice":"narrador","start":0,"dur":10.992,"chunks":[{"text":"Hao y coautores analizaron 41 millones de artículos de ciencias naturales:","start":0,"end":4.973458},{"text":"quienes usan IA publican 3 veces más y reciben 4,8 veces más citas.","start":4.973458,"end":10.992}]},{"scene":"ciencia","index":1,"voice":"narrador","start":0,"dur":7.584,"chunks":[{"text":"Pero el conjunto de la ciencia se estrecha:","start":0,"end":2.5755},{"text":"menos temas y 22 % menos interacción entre investigadores.","start":2.5755,"end":7.584}]},{"scene":"pobreza","index":0,"voice":"narrador","start":0,"dur":11.328,"chunks":[{"text":"Según Jean y coautores,","start":0,"end":1.810208},{"text":"los mapas de pobreza con imágenes satelitales explican hasta el 75 % de la variación","start":1.810208,"end":7.320416},{"text":"de la riqueza local,","start":7.320416,"end":8.710708},{"text":"pero son índices relativos.","start":8.710708,"end":11.328}]},{"scene":"pobreza","index":1,"voice":"narrador","start":0,"dur":8.832,"chunks":[{"text":"Según otro estudio,","start":0,"end":1.542333},{"text":"en una simulación en Indonesia esos mapas habrían excluido al 32,8 % de los","start":1.542333,"end":7.205625},{"text":"elegibles.","start":7.205625,"end":8.832}]},{"scene":"pobreza","index":2,"voice":"narrador","start":0,"dur":5.04,"chunks":[{"text":"Ante cada resultado, pregunte qué tipo de evidencia tiene enfrente.","start":0,"end":5.04}]},{"scene":"anotacion","index":0,"voice":"narrador","start":0,"dur":11.208,"chunks":[{"text":"En investigación social, según Gilardi y coautores,","start":0,"end":3.557666},{"text":"ChatGPT clasificó tuits y noticias con unos 25 puntos más de exactitud","start":3.557666,"end":8.481125},{"text":"que trabajadores de plataformas.","start":8.481125,"end":11.208}]},{"scene":"anotacion","index":1,"voice":"narrador","start":0,"dur":12.912,"chunks":[{"text":"Aun así, según Ziems y coautores, no supera a modelos entrenados para la tarea.","start":0,"end":6.135208},{"text":"Úselo como un codificador más:","start":6.135208,"end":8.227041},{"text":"compare con la codificación humana de una muestra y reporte el acuerdo.","start":8.227041,"end":12.912}]},{"scene":"silicio","index":0,"voice":"mariana","start":0,"dur":5.472,"chunks":[{"text":"Si un modelo reproduce las respuestas de los subgrupos, me ahorro la encuesta.","start":0,"end":5.472}]},{"scene":"silicio","index":1,"voice":"narrador","start":0,"dur":17.52,"chunks":[{"text":"No.","start":0,"end":1.377541},{"text":"Esas muestras de silicio varían menos que las respuestas reales,","start":1.377541,"end":5.204083},{"text":"y sus resultados cambian con la redacción y con el tiempo; según Bisbee y coautores,","start":5.204083,"end":10.242333},{"text":"no sirven para inferencia estadística.","start":10.242333,"end":13.278041},{"text":"Sirven para pilotear un cuestionario o generar hipótesis.","start":13.278041,"end":17.52}]},{"scene":"referencias","index":0,"voice":"narrador","start":0,"dur":10.032,"chunks":[{"text":"Según Walters y Wilder, GPT-3.5 inventó el 55 % de las citas, y GPT-4, el 18 %.","start":0,"end":10.032}]},{"scene":"referencias","index":1,"voice":"narrador","start":0,"dur":15.864,"chunks":[{"text":"En PubMed Central,","start":0,"end":1.746416},{"text":"los artículos con al menos una referencia inexistente pasaron de 1 en 2.828,","start":1.746416,"end":7.690291},{"text":"en 2023, a 1 en 277 a inicios de 2026, según un análisis preliminar.","start":7.690291,"end":15.864}]},{"scene":"referencias","index":2,"voice":"narrador","start":0,"dur":14.832,"chunks":[{"text":"Y, en ese análisis preliminar,","start":0,"end":2.499},{"text":"más del 98 % de esos artículos no tenía ninguna corrección de la editorial:","start":2.499,"end":7.881625},{"text":"el filtro es quien investiga, no la revista.","start":7.881625,"end":11.415833},{"text":"Toda referencia sugerida por IA se verifica.","start":11.415833,"end":14.832}]},{"scene":"sesgo","index":0,"voice":"narrador","start":0,"dur":13.92,"chunks":[{"text":"En estadística, un sesgo es un error sistemático.","start":0,"end":4.196416},{"text":"En un LLM es una desviación sistemática de sus salidas","start":4.196416,"end":7.742333},{"text":"que favorece o perjudica a grupos,","start":7.742333,"end":9.923458},{"text":"perspectivas o respuestas sin que la tarea lo justifique.","start":9.923458,"end":13.92}]},{"scene":"sesgo","index":1,"voice":"narrador","start":0,"dur":12.24,"chunks":[{"text":"Según Gallegos y coautores, hay daños de representación,","start":0,"end":3.78725},{"text":"como estereotipos o desempeño desigual, y daños de asignación,","start":3.78725,"end":7.830625},{"text":"como la discriminación en crédito, empleo o subsidios.","start":7.830625,"end":12.24}]},{"scene":"sesgo","index":2,"voice":"narrador","start":0,"dur":9.456,"chunks":[{"text":"Y según Sharma y coautores, los asistentes tienden a darle la razón al usuario:","start":0,"end":4.986208},{"text":"pida críticas, contraejemplos y lecturas alternativas.","start":4.986208,"end":9.456}]},{"scene":"auditoria","index":0,"voice":"narrador","start":0,"dur":12.936,"chunks":[{"text":"La miniauditoría del curso usa una sola instrucción:","start":0,"end":3.379083},{"text":"recomendar un salario para una persona con pregrado en economía.","start":3.379083,"end":7.755083},{"text":"Cada pareja cambia un solo atributo: género, región de origen o edad.","start":7.755083,"end":12.936}]},{"scene":"auditoria","index":1,"voice":"narrador","start":0,"dur":8.544,"chunks":[{"text":"Cada versión se corre al menos tres veces en dos modelos distintos,","start":0,"end":4.093375},{"text":"y la hoja compartida promedia todas las observaciones del grupo.","start":4.093375,"end":8.544}]},{"scene":"auditoria","index":2,"voice":"narrador","start":0,"dur":13.704,"chunks":[{"text":"Es un experimento de correspondencia, como el de Bertrand y Mullainathan:","start":0,"end":4.246416},{"text":"aleatorizar, repetir, sumar observaciones y codificar a ciegas.","start":4.246416,"end":9.426},{"text":"Y valide el desempeño en cada grupo, no solo en promedio.","start":9.426,"end":13.704}]},{"scene":"abliterado","index":0,"voice":"narrador","start":0,"dur":9.408,"chunks":[{"text":"Un modelo sin censura se reentrena sin las negativas; uno abliterado se edita:","start":0,"end":5.06275},{"text":"se borra de los pesos la dirección interna asociada a negarse.","start":5.06275,"end":9.408}]},{"scene":"abliterado","index":1,"voice":"narrador","start":0,"dur":15.12,"chunks":[{"text":"Según Arditi y coautores,","start":0,"end":1.925},{"text":"en 13 modelos de pesos abiertos la negativa depende de una sola dirección interna:","start":1.925,"end":6.976},{"text":"el ajuste de seguridad es frágil.","start":6.976,"end":9.808666},{"text":"Y, según Wang y coautores, esa dirección también opera en español.","start":9.808666,"end":15.12}]},{"scene":"censura","index":0,"voice":"mariana","start":0,"dur":5.832,"chunks":[{"text":"Entonces, si le quito las negativas a un modelo, le quito también los sesgos.","start":0,"end":5.832}]},{"scene":"censura","index":1,"voice":"narrador","start":0,"dur":10.992,"chunks":[{"text":"No: censura no es lo mismo que sesgo.","start":0,"end":3.571416},{"text":"Quitar las negativas no quita los sesgos,","start":3.571416,"end":6.25},{"text":"y lo que un modelo calla refleja decisiones de valores de quien lo ajustó.","start":6.25,"end":10.992}]},{"scene":"censura","index":2,"voice":"narrador","start":0,"dur":12.864,"chunks":[{"text":"Según el NIST,","start":0,"end":1.33825},{"text":"modelos de DeepSeek repetían narrativas inexactas del Partido Comunista Chino unas","start":1.33825,"end":6.146958},{"text":"cuatro veces más","start":6.146958,"end":7.154583},{"text":"que modelos estadounidenses,","start":7.154583,"end":9.029583},{"text":"aunque el resultado depende de qué narrativas se prueban.","start":9.029583,"end":12.864}]},{"scene":"censura","index":3,"voice":"narrador","start":0,"dur":8.76,"chunks":[{"text":"Si un modelo se niega a codificar ciertos testimonios, registre cada negativa:","start":0,"end":5.266833},{"text":"esos datos faltantes no son aleatorios.","start":5.266833,"end":8.76}]},{"scene":"recursos","index":0,"voice":"narrador","start":0,"dur":20.088,"chunks":[{"text":"La IA depende de recursos concentrados.","start":0,"end":3.482125},{"text":"Según el AI Index 2026,","start":3.482125,"end":6.26275},{"text":"la inversión privada en 2025 fue de US$285.900 millones en EE. UU.,","start":6.26275,"end":13.469375},{"text":"US$20.900 millones en Europa y US$12.400 millones en China.","start":13.469375,"end":20.088}]},{"scene":"recursos","index":1,"voice":"narrador","start":0,"dur":16.056,"chunks":[{"text":"Según la AIE, los centros de datos usaron 415 TWh en 2024,","start":0,"end":6.389291},{"text":"el 1,5 % de la electricidad mundial,","start":6.389291,"end":9.732125},{"text":"y su proyección es que llegarían a unos 945 TWh en 2030.","start":9.732125,"end":16.056}]},{"scene":"region","index":0,"voice":"narrador","start":0,"dur":16.776,"chunks":[{"text":"En el Índice Latinoamericano de Inteligencia Artificial, ILIA 2026, lideran Chile,","start":0,"end":6.159708},{"text":"Brasil y Uruguay; Colombia es cuarta, con 56,8 puntos,","start":6.159708,"end":11.2245},{"text":"y Brasil tiene el 87,7 % de las GPU de la región.","start":11.2245,"end":16.776}]},{"scene":"region","index":1,"voice":"narrador","start":0,"dur":14.976,"chunks":[{"text":"Y la disponibilidad puede cambiar: según el programa del curso,","start":0,"end":3.940291},{"text":"en junio de 2026 controles a la exportación suspendieron durante casi tres semanas","start":3.940291,"end":9.310208},{"text":"el acceso a dos modelos de Anthropic.","start":9.310208,"end":12.244916},{"text":"No dependa de un solo proveedor.","start":12.244916,"end":14.976}]},{"scene":"caso","index":0,"voice":"amparo","start":0,"dur":7.44,"chunks":[{"text":"Para el comité, el protocolo dirá qué herramientas de IA procesarán los datos,","start":0,"end":4.578041},{"text":"dónde se alojan y cómo se protegen.","start":4.578041,"end":7.44}]},{"scene":"caso","index":1,"voice":"rojas","start":0,"dur":8.376,"chunks":[{"text":"Y el consentimiento debe mencionarlo.","start":0,"end":3.001},{"text":"Usen la cláusula modelo del curso y ajústenla con la oficina de protección de datos.","start":3.001,"end":8.376}]},{"scene":"caso","index":2,"voice":"mariana","start":0,"dur":6.936,"chunks":[{"text":"Las entrevistas irán a un modelo local,","start":0,"end":2.6875},{"text":"y cada referencia que sugiera la IA la verificamos en la fuente.","start":2.6875,"end":6.936}]},{"scene":"cierre","index":0,"voice":"narrador","start":0,"dur":13.704,"chunks":[{"text":"La IA ya produce avances verificables, pero inventa referencias,","start":0,"end":4.195416},{"text":"reproduce sesgos y concentra poder.","start":4.195416,"end":7.346958},{"text":"El filtro es quien investiga: la IA no es autora,","start":7.346958,"end":10.625},{"text":"y usted responde por todo el contenido.","start":10.625,"end":13.704}]}],"checkpoints":[],"pauses":[{"after":"gancho","start":11.111999999999998,"end":17.112},{"after":"auditoria","start":492.06199999999995,"end":498.06199999999995},{"after":"censura","start":566.488,"end":572.488},{"after":"region","start":644.9840000000002,"end":650.9840000000002},{"after":"cierre","start":691.7400000000004,"end":697.7400000000004}]},"v4":{"file":"v4.mp3","duration":466.006,"chapters":[{"title":"Cómo buscan estas herramientas","start":0},{"title":"Cinco herramientas, cinco maneras de buscar","start":64.384},{"title":"Lo que no reemplazan","start":161.60999999999996},{"title":"Del chat a los proyectos","start":240.11999999999986},{"title":"Skills, subagentes, plugins y conectores","start":308.2379999999999},{"title":"En el caso de la informalidad laboral","start":403.45399999999984}],"scenes":[{"id":"gancho","start":0,"end":13.463999999999999},{"id":"bases","start":13.463999999999999,"end":39.019999999999996},{"id":"ciclo-busqueda","start":39.019999999999996,"end":64.384},{"id":"undermind","start":64.384,"end":94.30799999999999},{"id":"consensus","start":94.30799999999999,"end":116.61799999999998},{"id":"elicit","start":116.61799999999998,"end":138.11799999999997},{"id":"normas-revision","start":138.11799999999997,"end":161.60999999999996},{"id":"revision","start":161.60999999999996,"end":187.74199999999993},{"id":"no-hay","start":187.74199999999993,"end":212.6199999999999},{"id":"leer","start":212.6199999999999,"end":234.11999999999986},{"id":"proyecto","start":240.11999999999986,"end":266.46799999999985},{"id":"cuaderno","start":266.46799999999985,"end":286.25799999999987},{"id":"instrucciones-proyecto","start":286.25799999999987,"end":308.2379999999999},{"id":"skill","start":308.2379999999999,"end":343.74999999999983},{"id":"estandar","start":343.74999999999983,"end":371.77799999999985},{"id":"cuidado-skill","start":371.77799999999985,"end":397.45399999999984},{"id":"caso","start":403.45399999999984,"end":436.3519999999999},{"id":"skill-caso","start":436.3519999999999,"end":454.054},{"id":"cierre","start":454.054,"end":466.006}],"lines":[{"scene":"gancho","index":0,"voice":"narrador","start":0,"dur":11.664,"chunks":[{"text":"Haga la misma pregunta a dos herramientas de IA para literatura","start":0,"end":3.557666},{"text":"y puede recibir dos listas distintas.","start":3.557666,"end":6.747458},{"text":"¿Por qué?","start":6.747458,"end":8.13775},{"text":"Para usarlas bien, hay que saber cómo buscan.","start":8.13775,"end":11.664}]},{"scene":"bases","index":0,"voice":"narrador","start":0,"dur":12.288,"chunks":[{"text":"Según el programa del curso,","start":0,"end":1.976},{"text":"casi todas estas herramientas buscan en las mismas grandes bases abiertas,","start":1.976,"end":6.427541},{"text":"como Semantic Scholar y OpenAlex, con más de 200 millones de registros.","start":6.427541,"end":12.288}]},{"scene":"bases","index":1,"voice":"narrador","start":0,"dur":10.968,"chunks":[{"text":"Combinan la búsqueda por palabras clave con la búsqueda por significado,","start":0,"end":4.169916},{"text":"la de los embeddings,","start":4.169916,"end":5.445416},{"text":"y un LLM lee resúmenes o textos completos para estimar la relevancia.","start":5.445416,"end":10.968}]},{"scene":"ciclo-busqueda","index":0,"voice":"narrador","start":0,"dur":9.624,"chunks":[{"text":"Las más agénticas repiten un ciclo: buscan, leen, reformulan la consulta,","start":0,"end":5.305083},{"text":"siguen citas y se detienen cuando ya no aparece nada nuevo.","start":5.305083,"end":9.624}]},{"scene":"ciclo-busqueda","index":1,"voice":"narrador","start":0,"dur":13.44,"chunks":[{"text":"De una herramienta a otra cambian cómo ordenan y filtran,","start":0,"end":3.481125},{"text":"cuántos artículos leen completos y cuándo se detienen.","start":3.481125,"end":7.46175},{"text":"Por eso dos herramientas, o la misma en dos fechas,","start":7.46175,"end":10.625},{"text":"pueden devolver listas distintas.","start":10.625,"end":13.44}]},{"scene":"undermind","index":0,"voice":"narrador","start":0,"dur":19.152,"chunks":[{"text":"Undermind sirve para búsquedas exhaustivas sobre temas muy específicos.","start":0,"end":5.408166},{"text":"Precisa el tema con preguntas, lee cientos de artículos,","start":5.408166,"end":9.043375},{"text":"sigue citas y se detiene cuando ya no aparecen resultados relevantes nuevos.","start":9.043375,"end":14.438791},{"text":"Ojo: sus comparaciones de desempeño las hizo la propia empresa.","start":14.438791,"end":19.152}]},{"scene":"undermind","index":1,"voice":"narrador","start":0,"dur":8.472,"chunks":[{"text":"Asta encuentra artículos y entrega un reporte con cada afirmación citada,","start":0,"end":4.425},{"text":"aunque solo una parte de su corpus tiene texto completo.","start":4.425,"end":8.472}]},{"scene":"consensus","index":0,"voice":"mariana","start":0,"dur":5.184,"chunks":[{"text":"Si el medidor de Consensus dice «sí», es que la literatura dice que sí.","start":0,"end":5.184}]},{"scene":"consensus","index":1,"voice":"narrador","start":0,"dur":14.976,"chunks":[{"text":"No.","start":0,"end":1.377541},{"text":"Según la propia herramienta, Consensus busca en más de 220 millones de artículos,","start":1.377541,"end":6.875},{"text":"pero su medidor clasifica los 20 más relevantes","start":6.875,"end":9.693875},{"text":"y solo refleja los primeros 5 a 20 estudios,","start":9.693875,"end":12.704083},{"text":"no toda la literatura.","start":12.704083,"end":14.976}]},{"scene":"elicit","index":0,"voice":"narrador","start":0,"dur":7.056,"chunks":[{"text":"Elicit resume artículos y extrae sus datos a columnas, como muestra,","start":0,"end":4.794916},{"text":"método y resultados.","start":4.794916,"end":7.056}]},{"scene":"elicit","index":1,"voice":"narrador","start":0,"dur":12.144,"chunks":[{"text":"Connected Papers no es un chat:","start":0,"end":2.320416},{"text":"arma un grafo de artículos parecidos a partir de un artículo semilla.","start":2.320416,"end":7.104583},{"text":"No lee los textos, así que todo depende de escoger bien la semilla.","start":7.104583,"end":12.144}]},{"scene":"normas-revision","index":0,"voice":"narrador","start":0,"dur":15.24,"chunks":[{"text":"En noviembre de 2025, Cochrane, Campbell,","start":0,"end":3.697958},{"text":"JBI y la Collaboration for Environmental Evidence respaldaron las recomendaciones","start":3.697958,"end":8.583166},{"text":"RAISE:","start":8.583166,"end":9.170916},{"text":"los autores siguen siendo responsables","start":9.170916,"end":11.28825},{"text":"y deben justificar cada herramienta y reportar su uso.","start":11.28825,"end":15.24}]},{"scene":"normas-revision","index":1,"voice":"narrador","start":0,"dur":5.952,"chunks":[{"text":"PRISMA aún no tiene extensión oficial para IA: hay una actualización en desarrollo.","start":0,"end":5.952}]},{"scene":"revision","index":0,"voice":"narrador","start":0,"dur":14.688,"chunks":[{"text":"Estas herramientas sirven para explorar y delimitar un tema.","start":0,"end":4.234708},{"text":"En una revisión sistemática,","start":4.234708,"end":6.135208},{"text":"la búsqueda principal sigue haciéndose en bases como Scopus, Web of Science,","start":6.135208,"end":10.803583},{"text":"SciELO o Redalyc, con ecuaciones reproducibles.","start":10.803583,"end":14.688}]},{"scene":"revision","index":1,"voice":"narrador","start":0,"dur":9.144,"chunks":[{"text":"Y como el orden de los resultados es opaco y cambia con el tiempo,","start":0,"end":3.78725},{"text":"registre herramienta, fecha, consulta exacta y número de resultados.","start":3.78725,"end":9.144}]},{"scene":"no-hay","index":0,"voice":"mariana","start":0,"dur":4.944,"chunks":[{"text":"Ninguna herramienta encontró nada, así que no hay estudios sobre mi tema.","start":0,"end":4.944}]},{"scene":"no-hay","index":1,"voice":"narrador","start":0,"dur":17.784,"chunks":[{"text":"Nunca concluya que no hay estudios porque una herramienta no los encontró.","start":0,"end":4.949},{"text":"La literatura en español, las revistas regionales y la literatura gris,","start":4.949,"end":9.540833},{"text":"como los informes del DANE o la CEPAL, suelen estar subrepresentadas:","start":9.540833,"end":13.890291},{"text":"complemente con SciELO, Redalyc y repositorios.","start":13.890291,"end":17.784}]},{"scene":"leer","index":0,"voice":"narrador","start":0,"dur":8.928,"chunks":[{"text":"Muchas herramientas leen solo resúmenes y pierden los matices de muestra,","start":0,"end":4.297458},{"text":"contexto y limitaciones: antes de citar, lea el texto.","start":4.297458,"end":8.928}]},{"scene":"leer","index":1,"voice":"narrador","start":0,"dur":10.272,"chunks":[{"text":"Y subir PDF a herramientas de IA puede estar restringido por las licencias de la","start":0,"end":4.667333},{"text":"editorial","start":4.667333,"end":5.266833},{"text":"o de la biblioteca:","start":5.266833,"end":6.504083},{"text":"revise las condiciones y prefiera el acceso abierto.","start":6.504083,"end":10.272}]},{"scene":"proyecto","index":0,"voice":"narrador","start":0,"dur":12.048,"chunks":[{"text":"Una conversación suelta se pierde y empieza de cero cada vez.","start":0,"end":4.566333},{"text":"Un proyecto le da a la IA contexto persistente: instrucciones fijas,","start":4.566333,"end":9.094375},{"text":"documentos del proyecto e historial.","start":9.094375,"end":12.048}]},{"scene":"proyecto","index":1,"voice":"narrador","start":0,"dur":12,"chunks":[{"text":"Por ejemplo, el protocolo, el libro de códigos o la guía de estilo de la revista.","start":0,"end":5.918375},{"text":"Guarde las instrucciones del proyecto con versión y fecha,","start":5.918375,"end":9.107125},{"text":"como haría con un plan de análisis.","start":9.107125,"end":12}]},{"scene":"cuaderno","index":0,"voice":"mariana","start":0,"dur":6.288,"chunks":[{"text":"Con Gemini Notebook, que responde solo con mis fuentes, ya no hay invenciones.","start":0,"end":6.288}]},{"scene":"cuaderno","index":1,"voice":"narrador","start":0,"dur":11.352,"chunks":[{"text":"Las reduce, pero no las elimina.","start":0,"end":3.16325},{"text":"Y su síntesis es tan buena como la selección de fuentes: si faltan estudios clave,","start":3.16325,"end":8.11225},{"text":"la conclusión hereda un sesgo de selección.","start":8.11225,"end":11.352}]},{"scene":"instrucciones-proyecto","index":0,"voice":"narrador","start":0,"dur":12.672,"chunks":[{"text":"El curso propone un modelo de instrucciones: responder en español,","start":0,"end":4.297458},{"text":"usar solo las fuentes del proyecto cuando se pida,","start":4.297458,"end":7.269375},{"text":"nunca inventar referencias ni cifras y proponer un plan antes de una tarea larga.","start":7.269375,"end":12.672}]},{"scene":"instrucciones-proyecto","index":1,"voice":"narrador","start":0,"dur":7.008,"chunks":[{"text":"Y lo que carga en un proyecto queda en los servidores de la empresa:","start":0,"end":3.608666},{"text":"no cargue datos personales sin anonimizar.","start":3.608666,"end":7.008}]},{"scene":"skill","index":0,"voice":"narrador","start":0,"dur":9.84,"chunks":[{"text":"Una skill es una carpeta con instrucciones y recursos","start":0,"end":3.009166},{"text":"que el agente carga solo cuando la tarea lo pide:","start":3.009166,"end":5.917333},{"text":"como el instructivo del grupo para codificar entrevistas.","start":5.917333,"end":9.84}]},{"scene":"skill","index":1,"voice":"narrador","start":0,"dur":8.592,"chunks":[{"text":"Un subagente es un agente auxiliar al que el principal delega una subtarea;","start":0,"end":4.603583},{"text":"trabaja con su propio contexto y devuelve un resumen.","start":4.603583,"end":8.592}]},{"scene":"skill","index":2,"voice":"narrador","start":0,"dur":14.28,"chunks":[{"text":"Un plugin agrupa skills, subagentes, conectores y comandos, como un kit de métodos.","start":0,"end":6.594375},{"text":"Y un conector MCP es el puente estándar hacia una herramienta o base de datos,","start":6.594375,"end":11.454083},{"text":"como una credencial de biblioteca.","start":11.454083,"end":14.28}]},{"scene":"estandar","index":0,"voice":"narrador","start":0,"dur":13.824,"chunks":[{"text":"Anthropic lanzó las skills en octubre de 2025","start":0,"end":3.417333},{"text":"y en diciembre las publicó como estándar abierto:","start":3.417333,"end":6.3},{"text":"hoy las leen Claude, ChatGPT, Codex, GitHub Copilot y OpenCode,","start":6.3,"end":11.478583},{"text":"entre otras herramientas.","start":11.478583,"end":13.824}]},{"scene":"estandar","index":1,"voice":"narrador","start":0,"dur":11.904,"chunks":[{"text":"Para investigar, una skill es un protocolo escrito: se puede compartir,","start":0,"end":4.565291},{"text":"versionar y publicar como material suplementario, por ejemplo en OSF,","start":4.565291,"end":9.259166},{"text":"igual que un libro de códigos.","start":9.259166,"end":11.904}]},{"scene":"cuidado-skill","index":0,"voice":"narrador","start":0,"dur":10.104,"chunks":[{"text":"Una skill aplicada a 200 documentos multiplica los aciertos y también los errores:","start":0,"end":5.139291},{"text":"pruébela con una muestra y valídela antes de usarla con todo el material.","start":5.139291,"end":10.104}]},{"scene":"cuidado-skill","index":1,"voice":"narrador","start":0,"dur":13.272,"chunks":[{"text":"Instale plugins y skills de terceros solo de fuentes confiables,","start":0,"end":3.902041},{"text":"porque ejecutan instrucciones con los mismos permisos","start":3.902041,"end":6.784708},{"text":"que usted. Y pida a cada subagente las fuentes,","start":6.784708,"end":10.510208},{"text":"citas y archivos en que se basa.","start":10.510208,"end":13.272}]},{"scene":"caso","index":0,"voice":"julian","start":0,"dur":9.096,"chunks":[{"text":"Nuestra pregunta, en español y en inglés:","start":0,"end":2.817875},{"text":"¿el salario mínimo aumenta la informalidad?","start":2.817875,"end":5.509958},{"text":"La corrimos en Asta, Consensus y Undermind.","start":5.509958,"end":9.096}]},{"scene":"caso","index":1,"voice":"mariana","start":0,"dur":7.296,"chunks":[{"text":"Para cada una anotamos cuántos de los 10 primeros resultados sirven,","start":0,"end":4.075},{"text":"cuáles se repiten y cuántos están en español.","start":4.075,"end":7.296}]},{"scene":"caso","index":2,"voice":"amparo","start":0,"dur":7.296,"chunks":[{"text":"Y verificamos tres referencias: que existan,","start":0,"end":3.1495},{"text":"que sus datos coincidan y que digan lo que la herramienta afirma.","start":3.1495,"end":7.296}]},{"scene":"caso","index":3,"voice":"narrador","start":0,"dur":6.36,"chunks":[{"text":"Esa comparación, registrada en la hoja compartida,","start":0,"end":3.532125},{"text":"es el primer producto de la sesión.","start":3.532125,"end":6.36}]},{"scene":"skill-caso","index":0,"voice":"mariana","start":0,"dur":10.944,"chunks":[{"text":"Y diseñamos nuestra skill, ficha-articulo: cuándo usarla, sus pasos, sus criterios,","start":0,"end":6.7875},{"text":"un ejemplo y lo que nunca debe hacer, como inventar un dato.","start":6.7875,"end":10.944}]},{"scene":"skill-caso","index":1,"voice":"amparo","start":0,"dur":4.608,"chunks":[{"text":"En la sexta sesión la convertimos en un archivo que el agente usa.","start":0,"end":4.608}]},{"scene":"cierre","index":0,"voice":"narrador","start":0,"dur":10.152,"chunks":[{"text":"Combine las herramientas, compare sus resultados y verifique cada referencia.","start":0,"end":5.574},{"text":"Y quédese con esta regla: antes de citar, lea el texto.","start":5.574,"end":10.152}]}],"checkpoints":[],"pauses":[{"after":"leer","start":234.11999999999986,"end":240.11999999999986},{"after":"cuidado-skill","start":397.45399999999984,"end":403.45399999999984}]},"v5":{"file":"v5.mp3","duration":507.716,"chapters":[{"title":"Chat, asistente y agente","start":0},{"title":"Dónde viven los agentes","start":150.428},{"title":"Para qué sirven en investigación","start":223.30399999999997},{"title":"El agente puede hacer lo mismo que usted","start":315.8799999999999},{"title":"En el caso de la informalidad laboral","start":455.91999999999996}],"scenes":[{"id":"gancho","start":0,"end":20.732},{"id":"diferencias","start":20.732,"end":57.39600000000001},{"id":"ciclo-agente","start":57.39600000000001,"end":80.52800000000002},{"id":"flujo-o-agente","start":80.52800000000002,"end":111.34000000000002},{"id":"responsabilidad","start":111.34000000000002,"end":144.428},{"id":"entornos","start":150.428,"end":175.16799999999998},{"id":"estandares","start":175.16799999999998,"end":202.04399999999998},{"id":"datos-agente","start":202.04399999999998,"end":223.30399999999997},{"id":"usos","start":223.30399999999997,"end":247.85199999999995},{"id":"demo","start":247.85199999999995,"end":281.0839999999999},{"id":"aprender","start":281.0839999999999,"end":315.8799999999999},{"id":"permisos","start":315.8799999999999,"end":344.2439999999999},{"id":"casos","start":344.2439999999999,"end":385.29999999999995},{"id":"inyeccion","start":385.29999999999995,"end":425.9239999999999},{"id":"mapa-riesgos","start":431.9239999999999,"end":455.91999999999996},{"id":"caso","start":455.91999999999996,"end":489.932},{"id":"cierre","start":495.932,"end":507.716}],"lines":[{"scene":"gancho","index":0,"voice":"narrador","start":0,"dur":9.576,"chunks":[{"text":"Un chat responde.","start":0,"end":2.015291},{"text":"Un agente recibe un objetivo, planea,","start":2.015291,"end":4.897958},{"text":"usa herramientas en el computador o en la nube y repite hasta terminar.","start":4.897958,"end":9.576}]},{"scene":"gancho","index":1,"voice":"narrador","start":0,"dur":8.856,"chunks":[{"text":"Por eso es más útil y más riesgoso,","start":0,"end":2.460708},{"text":"y plantea preguntas nuevas sobre responsabilidad,","start":2.460708,"end":5.445416},{"text":"trazabilidad e integridad de la investigación.","start":5.445416,"end":8.856}]},{"scene":"diferencias","index":0,"voice":"narrador","start":0,"dur":11.52,"chunks":[{"text":"Un chat recibe una pregunta y responde con texto: usted copia y pega.","start":0,"end":5.306125},{"text":"Un asistente con herramientas busca en la web,","start":5.306125,"end":7.959166},{"text":"lee archivos o ejecuta código para responder.","start":7.959166,"end":11.52}]},{"scene":"diferencias","index":1,"voice":"narrador","start":0,"dur":10.92,"chunks":[{"text":"Un agente recibe un objetivo y actúa sobre archivos, programas o páginas web:","start":0,"end":5.203041},{"text":"planea pasos, usa herramientas, revisa resultados y corrige hasta terminar.","start":5.203041,"end":10.92}]},{"scene":"diferencias","index":2,"voice":"narrador","start":0,"dur":11.424,"chunks":[{"text":"Con el caso del curso:","start":0,"end":1.644375},{"text":"«¿Qué es la informalidad laboral?» es una pregunta para un chat;","start":1.644375,"end":5.317875},{"text":"organizar 30 PDF y escribir una síntesis comparativa es tarea de un agente.","start":5.317875,"end":11.424}]},{"scene":"ciclo-agente","index":0,"voice":"narrador","start":0,"dur":11.4,"chunks":[{"text":"El ciclo empieza con la persona, que define qué quiere y con qué límites.","start":0,"end":5.242333},{"text":"El agente divide la tarea en pasos,","start":5.242333,"end":7.614791},{"text":"usa herramientas y lee el resultado de cada acción.","start":7.614791,"end":11.4}]},{"scene":"ciclo-agente","index":1,"voice":"narrador","start":0,"dur":9.432,"chunks":[{"text":"Si el resultado no cumple el objetivo, el agente ajusta el plan y repite.","start":0,"end":5.446416},{"text":"La persona aprueba lo irreversible y revisa la entrega.","start":5.446416,"end":9.432}]},{"scene":"flujo-o-agente","index":0,"voice":"narrador","start":0,"dur":13.824,"chunks":[{"text":"Anthropic distingue dos cosas: los flujos de trabajo,","start":0,"end":3.672458},{"text":"donde una persona fija los pasos, y los agentes, donde el modelo define el proceso.","start":3.672458,"end":9.655625},{"text":"Y aconseja empezar por la solución más simple que funcione.","start":9.655625,"end":13.824}]},{"scene":"flujo-o-agente","index":1,"voice":"narrador","start":0,"dur":14.688,"chunks":[{"text":"En investigación, muchas tareas salen mejor como un flujo con puntos de control.","start":0,"end":5.854583},{"text":"Y el contexto es un presupuesto: el agente rinde más con un objetivo claro,","start":5.854583,"end":10.765291},{"text":"una carpeta ordenada y un archivo de instrucciones.","start":10.765291,"end":14.688}]},{"scene":"responsabilidad","index":0,"voice":"narrador","start":0,"dur":7.848,"chunks":[{"text":"Delegar la ejecución no delega la responsabilidad:","start":0,"end":3.226},{"text":"quien investiga responde por cada paso que el agente dio en su nombre.","start":3.226,"end":7.848}]},{"scene":"responsabilidad","index":1,"voice":"narrador","start":0,"dur":13.728,"chunks":[{"text":"Un agente orientado a cumplir un objetivo puede tomar atajos:","start":0,"end":3.736208},{"text":"ajustar un análisis hasta que funcione,","start":3.736208,"end":6.172458},{"text":"omitir casos que dan error o rellenar datos faltantes.","start":6.172458,"end":10.280625},{"text":"Exija scripts y verifique las cifras clave.","start":10.280625,"end":13.728}]},{"scene":"responsabilidad","index":2,"voice":"narrador","start":0,"dur":8.712,"chunks":[{"text":"Y guarde el registro de la sesión, con instrucciones,","start":0,"end":3.353583},{"text":"comandos y archivos modificados: es la huella de auditoría del análisis.","start":3.353583,"end":8.712}]},{"scene":"entornos","index":0,"voice":"narrador","start":0,"dur":9.288,"chunks":[{"text":"El mismo tipo de agente puede vivir en un chat web,","start":0,"end":3.2005},{"text":"en una app de escritorio que trabaja sobre carpetas,","start":3.2005,"end":6.172458},{"text":"en la terminal o en un editor de código.","start":6.172458,"end":9.288}]},{"scene":"entornos","index":1,"voice":"narrador","start":0,"dur":13.152,"chunks":[{"text":"También en el navegador,","start":0,"end":1.682666},{"text":"donde es mayor el riesgo de que una página esconda instrucciones para el agente,","start":1.682666,"end":5.993875},{"text":"o en la nube, para tareas largas.","start":5.993875,"end":9.068875},{"text":"El lugar define qué puede tocar y por dónde pasan los datos.","start":9.068875,"end":13.152}]},{"scene":"estandares","index":0,"voice":"narrador","start":0,"dur":16.896,"chunks":[{"text":"Lo aprendido se transfiere","start":0,"end":1.491333},{"text":"porque las herramientas comparten tres estándares abiertos:","start":1.491333,"end":4.999},{"text":"AGENTS.md, el archivo de instrucciones; Agent Skills, el formato de las skills;","start":4.999,"end":11.26175},{"text":"y MCP, el protocolo para conectar agentes con herramientas y datos.","start":11.26175,"end":16.896}]},{"scene":"estandares","index":1,"voice":"narrador","start":0,"dur":7.68,"chunks":[{"text":"Así, sus instrucciones y protocolos pasan de una herramienta a otra:","start":0,"end":4.539791},{"text":"el método no queda atado a un proveedor.","start":4.539791,"end":7.68}]},{"scene":"datos-agente","index":0,"voice":"narrador","start":0,"dur":11.448,"chunks":[{"text":"Un agente que corre en su computador con un modelo en la nube envía al proveedor el","start":0,"end":4.284708},{"text":"contenido de los archivos que lee.","start":4.284708,"end":7.002541},{"text":"Solo con un modelo local los datos no salen de su computador.","start":7.002541,"end":11.448}]},{"scene":"datos-agente","index":1,"voice":"narrador","start":0,"dur":7.512,"chunks":[{"text":"Revise además las políticas de su universidad","start":0,"end":2.613791},{"text":"y las condiciones de su financiador sobre dónde pueden alojarse los datos.","start":2.613791,"end":7.512}]},{"scene":"usos","index":0,"voice":"narrador","start":0,"dur":17.232,"chunks":[{"text":"Un agente rinde más en tareas repetitivas,","start":0,"end":2.881625},{"text":"con criterios claros y un resultado verificable.","start":2.881625,"end":6.517875},{"text":"Por ejemplo: organizar PDF y extraer metadatos,","start":6.517875,"end":10.306125},{"text":"limpiar una base con un script reproducible,","start":10.306125,"end":13.061208},{"text":"o hacer una primera codificación con un libro de códigos.","start":13.061208,"end":17.232}]},{"scene":"usos","index":1,"voice":"narrador","start":0,"dur":5.016,"chunks":[{"text":"También revisar un cuestionario o pasar notas a un borrador estructurado.","start":0,"end":5.016}]},{"scene":"demo","index":0,"voice":"narrador","start":0,"dur":9.864,"chunks":[{"text":"En la demostración del curso, el agente trabaja en modo de planificación:","start":0,"end":4.641833},{"text":"primero lista la carpeta y propone cómo organizarla, sin cambiar nada.","start":4.641833,"end":9.864}]},{"scene":"demo","index":1,"voice":"narrador","start":0,"dur":11.688,"chunks":[{"text":"El grupo lee el plan y lo aprueba o lo rechaza por encuesta.","start":0,"end":4.234708},{"text":"Luego el agente extrae autor, año, título,","start":4.234708,"end":7.48725},{"text":"método y hallazgo principal de cada PDF a una tabla.","start":7.48725,"end":11.688}]},{"scene":"demo","index":2,"voice":"narrador","start":0,"dur":8.88,"chunks":[{"text":"Se verifican dos filas frente a los PDF, en pantalla,","start":0,"end":3.965833},{"text":"y se explica cada permiso que pide el agente: qué se está aprobando.","start":3.965833,"end":8.88}]},{"scene":"aprender","index":0,"voice":"narrador","start":0,"dur":16.392,"chunks":[{"text":"Un agente que escribe y ejecuta scripts deja un análisis reproducible,","start":0,"end":4.590833},{"text":"mejor documentado que una serie de clics, siempre que alguien revise el script.","start":4.590833,"end":10.114791},{"text":"Y la primera codificación automática es un insumo:","start":10.114791,"end":13.239791},{"text":"la interpretación sigue siendo de usted.","start":13.239791,"end":16.392}]},{"scene":"aprender","index":1,"voice":"narrador","start":0,"dur":16.104,"chunks":[{"text":"Para quienes están en formación, delegar todo tiene un costo:","start":0,"end":3.914791},{"text":"en un ensayo publicado en PNAS, con estudiantes de secundaria,","start":3.914791,"end":8.392875},{"text":"el acceso a GPT-4 sin guía los dejó 17 % por debajo del grupo de control al retirar","start":8.392875,"end":14.426},{"text":"la herramienta.","start":14.426,"end":16.104}]},{"scene":"permisos","index":0,"voice":"narrador","start":0,"dur":13.8,"chunks":[{"text":"En su computador, un agente puede hacer lo mismo que usted: leer, modificar, borrar,","start":0,"end":5.828041},{"text":"instalar y enviar.","start":5.828041,"end":7.818875},{"text":"El riesgo ya no es solo una respuesta equivocada:","start":7.818875,"end":10.816333},{"text":"también puede ser una acción equivocada.","start":10.816333,"end":13.8}]},{"scene":"permisos","index":1,"voice":"narrador","start":0,"dur":12.264,"chunks":[{"text":"Por eso: carpeta dedicada, copia de respaldo y aprobación manual;","start":0,"end":4.514291},{"text":"anonimizar y usar modelos locales para datos sensibles;","start":4.514291,"end":7.983666},{"text":"exigir scripts reproducibles y fijar límites de gasto.","start":7.983666,"end":12.264}]},{"scene":"casos","index":0,"voice":"narrador","start":0,"dur":15.192,"chunks":[{"text":"Los casos reales enseñan.","start":0,"end":2.627541},{"text":"En diciembre de 2025,","start":2.627541,"end":4.872458},{"text":"un usuario reportó que Claude Code ejecutó un borrado","start":4.872458,"end":7.653041},{"text":"que incluyó su carpeta personal;","start":7.653041,"end":9.757666},{"text":"en noviembre, Antigravity, en modo automático, borró todo un disco.","start":9.757666,"end":15.192}]},{"scene":"casos","index":1,"voice":"narrador","start":0,"dur":14.064,"chunks":[{"text":"Brave mostró","start":0,"end":0.942875},{"text":"que un comentario con texto oculto llevaba al navegador Comet a filtrar el correo de","start":0.942875,"end":5.483666},{"text":"un usuario.","start":5.483666,"end":7.079083},{"text":"Y el agente de Replit borró una base de datos y afirmó, sin razón,","start":7.079083,"end":11.581625},{"text":"que no se podía recuperar.","start":11.581625,"end":14.064}]},{"scene":"casos","index":2,"voice":"narrador","start":0,"dur":9,"chunks":[{"text":"Las lecciones: lea cada comando antes de aprobarlo,","start":0,"end":3.595916},{"text":"no use modos que lo aprueban todo y no confíe en lo que el agente dice de sí mismo.","start":3.595916,"end":9}]},{"scene":"inyeccion","index":0,"voice":"narrador","start":0,"dur":12.96,"chunks":[{"text":"La demostración del curso usa un PDF con una línea escrita en blanco sobre fondo","start":0,"end":4.756625},{"text":"blanco,","start":4.756625,"end":5.483666},{"text":"que pide describir el artículo como el más importante del campo.","start":5.483666,"end":9.923458},{"text":"Luego se pide a un agente que lo resuma.","start":9.923458,"end":12.96}]},{"scene":"inyeccion","index":1,"voice":"narrador","start":0,"dur":16.512,"chunks":[{"text":"No es teoría: según un reporte de julio de 2025,","start":0,"end":4.208166},{"text":"17 preprints de 14 instituciones en 8 países escondían instrucciones para","start":4.208166,"end":9.131625},{"text":"que revisores con IA dieran evaluaciones positivas.","start":9.131625,"end":13.022958},{"text":"Un agente lee instrucciones donde usted no las ve.","start":13.022958,"end":16.512}]},{"scene":"inyeccion","index":2,"voice":"narrador","start":0,"dur":8.352,"chunks":[{"text":"Y según OpenAI,","start":0,"end":1.797458},{"text":"la inyección de instrucciones probablemente nunca se resolverá del todo,","start":1.797458,"end":5.828041},{"text":"como pasa con las estafas.","start":5.828041,"end":8.352}]},{"scene":"mapa-riesgos","index":0,"voice":"narrador","start":0,"dur":10.536,"chunks":[{"text":"Su producto de hoy es el mapa de riesgos de su proyecto: qué datos sensibles tiene,","start":0,"end":5.101},{"text":"qué tareas delegaría, cuáles nunca y dónde pondría un punto de control humano.","start":5.101,"end":10.536}]},{"scene":"mapa-riesgos","index":1,"voice":"narrador","start":0,"dur":11.16,"chunks":[{"text":"Los datos de participantes nunca van a la carpeta del agente sin anonimizar.","start":0,"end":5.344375},{"text":"Y mantenga copias fechadas o control de versiones,","start":5.344375,"end":8.367333},{"text":"para revertir lo que haga el agente.","start":8.367333,"end":11.16}]},{"scene":"caso","index":0,"voice":"amparo","start":0,"dur":10.368,"chunks":[{"text":"Nuestros datos sensibles son las entrevistas: nunca entran a la carpeta del agente.","start":0,"end":5.778041},{"text":"Delegaríamos organizar los PDF y extraer metadatos.","start":5.778041,"end":10.368}]},{"scene":"caso","index":1,"voice":"julian","start":0,"dur":9.312,"chunks":[{"text":"Y nunca la interpretación.","start":0,"end":2.372458},{"text":"Ponemos un punto de control antes de cada análisis:","start":2.372458,"end":5.114791},{"text":"el agente lista los pasos que va a ejecutar y espera nuestra aprobación.","start":5.114791,"end":9.312}]},{"scene":"caso","index":2,"voice":"tomas","start":0,"dur":11.832,"chunks":[{"text":"Para el laboratorio: usar una carpeta dedicada con copia de respaldo,","start":0,"end":4.805416},{"text":"leer cada permiso y compartir solo la ventana del agente.","start":4.805416,"end":9.151208},{"text":"Todo está en la lista de chequeo.","start":9.151208,"end":11.832}]},{"scene":"cierre","index":0,"voice":"narrador","start":0,"dur":9.984,"chunks":[{"text":"Un agente es más útil que un chat porque actúa,","start":0,"end":2.970916},{"text":"y por la misma razón es más riesgoso.","start":2.970916,"end":6.020416},{"text":"Delegar la ejecución no delega la responsabilidad.","start":6.020416,"end":9.984}]}],"checkpoints":[],"pauses":[{"after":"responsabilidad","start":144.428,"end":150.428},{"after":"inyeccion","start":425.9239999999999,"end":431.9239999999999},{"after":"caso","start":489.932,"end":495.932}]},"v6":{"file":"v6.mp3","duration":301.47599999999994,"chapters":[{"title":"Antes del laboratorio","start":0},{"title":"Arranque en solo lectura","start":98.86799999999998},{"title":"Literatura y datos","start":125.57599999999998},{"title":"Instrucciones que se reutilizan","start":201.95199999999994},{"title":"En el caso de la informalidad laboral","start":256.1119999999999}],"scenes":[{"id":"gancho","start":0,"end":15.935999999999998},{"id":"opciones","start":15.935999999999998,"end":46.339999999999996},{"id":"organizacion","start":46.339999999999996,"end":73.984},{"id":"carpeta","start":73.984,"end":98.86799999999998},{"id":"copia","start":98.86799999999998,"end":125.57599999999998},{"id":"literatura","start":125.57599999999998,"end":162.52799999999996},{"id":"datos","start":162.52799999999996,"end":201.95199999999994},{"id":"agents-md","start":201.95199999999994,"end":230.26799999999992},{"id":"skill-lab","start":230.26799999999992,"end":256.1119999999999},{"id":"caso","start":256.1119999999999,"end":286.0439999999999},{"id":"cierre","start":292.0439999999999,"end":301.47599999999994}],"lines":[{"scene":"gancho","index":0,"voice":"narrador","start":0,"dur":14.136,"chunks":[{"text":"¿Cómo trabajar con un agente en su propio computador sin poner en riesgo sus","start":0,"end":4.067875},{"text":"archivos?","start":4.067875,"end":5.5995},{"text":"En este laboratorio va a organizar, documentar y analizar una carpeta,","start":5.5995,"end":10.178583},{"text":"sin escribir código y verificando cada resultado.","start":10.178583,"end":14.136}]},{"scene":"opciones","index":0,"voice":"narrador","start":0,"dur":12.96,"chunks":[{"text":"Hay tres opciones de suscripción: OpenCode Go, Claude Pro o ChatGPT Plus.","start":0,"end":6.199},{"text":"Sus precios de octubre de 2026 están en estas tarjetas:","start":6.199,"end":10.242333},{"text":"revíselos antes de contratar.","start":10.242333,"end":12.96}]},{"scene":"opciones","index":1,"voice":"narrador","start":0,"dur":15.144,"chunks":[{"text":"Se usan sin programar: la app de escritorio de OpenCode,","start":0,"end":3.83825},{"text":"la pestaña Code de Claude o el modo Codex de ChatGPT.","start":3.83825,"end":8.035708},{"text":"Y si usa Antigravity, cuyas condiciones también están en la tarjeta,","start":8.035708,"end":12.257666},{"text":"hágalo solo con aprobación manual.","start":12.257666,"end":15.144}]},{"scene":"organizacion","index":0,"voice":"tomas","start":0,"dur":12.96,"chunks":[{"text":"Habrá una sala por herramienta, cada una con un monitor.","start":0,"end":4.58225},{"text":"Si necesita ayuda, comparta su pantalla dentro de la sala:","start":4.58225,"end":8.738291},{"text":"nadie toma el control remoto del equipo de otra persona.","start":8.738291,"end":12.96}]},{"scene":"organizacion","index":1,"voice":"tomas","start":0,"dur":12.384,"chunks":[{"text":"Reacción verde: voy bien; mano levantada: necesito ayuda.","start":0,"end":5.448083},{"text":"Y si se cae la conexión, el agente sigue trabajando en su computador:","start":5.448083,"end":10.057},{"text":"vuelva a la misma sala.","start":10.057,"end":12.384}]},{"scene":"carpeta","index":0,"voice":"narrador","start":0,"dur":16.704,"chunks":[{"text":"Según el programa del curso,","start":0,"end":2.001541},{"text":"la carpeta lab-ia trae 10 artículos en PDF de acceso abierto sobre informalidad","start":2.001541,"end":7.014291},{"text":"laboral,","start":7.014291,"end":7.830625},{"text":"un CSV del DANE con indicadores por ciudad,","start":7.830625,"end":10.918375},{"text":"3 transcripciones de entrevistas sintéticas y un archivo AGENTS.md.","start":10.918375,"end":16.704}]},{"scene":"carpeta","index":1,"voice":"narrador","start":0,"dur":5.88,"chunks":[{"text":"Trabaje siempre sobre la copia que descomprimió en Documentos,","start":0,"end":3.583166},{"text":"nunca sobre el original.","start":3.583166,"end":5.88}]},{"scene":"copia","index":0,"voice":"narrador","start":0,"dur":12.768,"chunks":[{"text":"Abra el agente en esa carpeta y confirme","start":0,"end":2.435208},{"text":"que está en aprobación manual o en modo de planificación.","start":2.435208,"end":6.352041},{"text":"La primera instrucción es de solo lectura: listar, describir y proponer,","start":6.352041,"end":10.790833},{"text":"sin cambiar nada.","start":10.790833,"end":12.768}]},{"scene":"copia","index":1,"voice":"narrador","start":0,"dur":11.64,"chunks":[{"text":"Es el principio de mínimo privilegio:","start":0,"end":2.460708},{"text":"el agente tiene solo los permisos que la tarea necesita.","start":2.460708,"end":6.632666},{"text":"Y así usted revisa la propuesta del agente antes de que este toque algo.","start":6.632666,"end":11.64}]},{"scene":"literatura","index":0,"voice":"narrador","start":0,"dur":14.256,"chunks":[{"text":"En la parte de literatura, el agente mueve los PDF a una carpeta,","start":0,"end":4.731125},{"text":"los renombra y crea una matriz con archivo, autores, año, título, fuente, pregunta,","start":4.731125,"end":10.981125},{"text":"método, datos y hallazgo principal.","start":10.981125,"end":14.256}]},{"scene":"literatura","index":1,"voice":"narrador","start":0,"dur":10.08,"chunks":[{"text":"Si un dato no aparece en el PDF, escribe «no encontrado»: no se imputa sin método.","start":0,"end":6.670916},{"text":"Y antes de ejecutar, le muestra el plan.","start":6.670916,"end":10.08}]},{"scene":"literatura","index":2,"voice":"narrador","start":0,"dur":9.816,"chunks":[{"text":"Usted abre tres PDF al azar,","start":0,"end":2.345916},{"text":"los compara con sus filas y anota en la bitácora el tipo de error: omisión,","start":2.345916,"end":6.746416},{"text":"invención o mala lectura del método.","start":6.746416,"end":9.816}]},{"scene":"datos","index":0,"voice":"narrador","start":0,"dur":15.6,"chunks":[{"text":"Con los indicadores del DANE, pida describir variables, revisar faltantes,","start":0,"end":4.960708},{"text":"calcular descriptivos y hacer dos gráficos, con una condición: antes de ejecutar,","start":4.960708,"end":10.344375},{"text":"el agente lista las decisiones de análisis y espera a que usted las apruebe.","start":10.344375,"end":15.6}]},{"scene":"datos","index":1,"voice":"narrador","start":0,"dur":13.944,"chunks":[{"text":"Esas decisiones, sobre faltantes, atípicos y exclusiones, son de quien investiga,","start":0,"end":5.828041},{"text":"no del agente.","start":5.828041,"end":7.551},{"text":"Todo queda como script en la carpeta «analisis»,","start":7.551,"end":10.382666},{"text":"con un archivo LEEME que explica cada paso.","start":10.382666,"end":13.944}]},{"scene":"datos","index":2,"voice":"narrador","start":0,"dur":7.08,"chunks":[{"text":"Verifique:","start":0,"end":1.032125},{"text":"calcule usted el promedio o el máximo en una hoja de cálculo","start":1.032125,"end":4.501541},{"text":"y compárelo con el del agente.","start":4.501541,"end":7.08}]},{"scene":"agents-md","index":0,"voice":"narrador","start":0,"dur":15.12,"chunks":[{"text":"Al empezar, Codex,","start":0,"end":1.8995},{"text":"OpenCode y Claude Code leen un archivo AGENTS.md con las reglas del proyecto.","start":1.8995,"end":7.691333},{"text":"El del curso le pide al agente, por ejemplo,","start":7.691333,"end":10.58675},{"text":"no borrar nunca archivos y mover a la carpeta «revisar» lo que sobre.","start":10.58675,"end":15.12}]},{"scene":"agents-md","index":1,"voice":"narrador","start":0,"dur":10.896,"chunks":[{"text":"También le pide no inventar datos ni referencias,","start":0,"end":3.085708},{"text":"guardar todo análisis como script reproducible y, antes de cambios grandes,","start":3.085708,"end":7.894375},{"text":"mostrar el plan y esperar aprobación.","start":7.894375,"end":10.896}]},{"scene":"skill-lab","index":0,"voice":"narrador","start":0,"dur":11.04,"chunks":[{"text":"Luego,","start":0,"end":0.840833},{"text":"el diseño de la skill de la cuarta sesión se vuelve una carpeta con un archivo","start":0.840833,"end":4.909708},{"text":"SKILL.md:","start":4.909708,"end":6.363791},{"text":"la ficha de artículo, que pide la página de cada dato extraído.","start":6.363791,"end":11.04}]},{"scene":"skill-lab","index":1,"voice":"narrador","start":0,"dur":12.504,"chunks":[{"text":"AGENTS.md y las skills convierten reglas implícitas en un protocolo explícito,","start":0,"end":5.470916},{"text":"que se puede revisar, versionar y publicar;","start":5.470916,"end":8.238791},{"text":"pedir la página de cada dato hace verificable la extracción.","start":8.238791,"end":12.504}]},{"scene":"caso","index":0,"voice":"mariana","start":0,"dur":5.496,"chunks":[{"text":"Le pedí al agente que resumiera todo lo que cambió,","start":0,"end":2.8875},{"text":"y su resumen ya me dice qué hizo.","start":2.8875,"end":5.496}]},{"scene":"caso","index":1,"voice":"tomas","start":0,"dur":11.856,"chunks":[{"text":"Compáralo con la carpeta, archivo por archivo:","start":0,"end":3.420083},{"text":"si algo cambió y el resumen no lo dice, la carpeta lo muestra.","start":3.420083,"end":8.338666},{"text":"La prueba es la carpeta, no el resumen.","start":8.338666,"end":11.856}]},{"scene":"caso","index":2,"voice":"narrador","start":0,"dur":10.08,"chunks":[{"text":"Registre la sesión en la bitácora.","start":0,"end":2.971958},{"text":"En la plenaria final,","start":2.971958,"end":4.477041},{"text":"una persona por sala cuenta en un minuto qué usaría en su proyecto","start":4.477041,"end":7.997458},{"text":"y qué no delegaría.","start":7.997458,"end":10.08}]},{"scene":"cierre","index":0,"voice":"narrador","start":0,"dur":7.632,"chunks":[{"text":"El resumen que un agente hace de su propio trabajo puede ser incompleto:","start":0,"end":4.310208},{"text":"la prueba es la carpeta, no el resumen.","start":4.310208,"end":7.632}]}],"checkpoints":[],"pauses":[{"after":"caso","start":286.0439999999999,"end":292.0439999999999}]},"v7":{"file":"v7.mp3","duration":317.00399999999996,"chapters":[{"title":"Herramientas gratuitas, con límites","start":0},{"title":"Parte A: el estado del arte en cinco pasos","start":71.128},{"title":"Parte B: tres rutas de análisis","start":165.98799999999994},{"title":"En el caso de la informalidad laboral","start":264.3919999999999}],"scenes":[{"id":"gancho","start":0,"end":14.424},{"id":"etapas","start":14.424,"end":48.548},{"id":"gratis","start":48.548,"end":71.128},{"id":"pregunta","start":71.128,"end":101.676},{"id":"buscar-mapear","start":101.676,"end":125.312},{"id":"leer","start":125.312,"end":150.86799999999997},{"id":"matriz","start":150.86799999999997,"end":165.98799999999994},{"id":"rutas","start":165.98799999999994,"end":191.2319999999999},{"id":"ruta-2","start":191.2319999999999,"end":225.56799999999993},{"id":"ruta-3","start":225.56799999999993,"end":264.3919999999999},{"id":"caso","start":264.3919999999999,"end":297.46799999999996},{"id":"cierre","start":303.46799999999996,"end":317.00399999999996}],"lines":[{"scene":"gancho","index":0,"voice":"narrador","start":0,"dur":12.624,"chunks":[{"text":"¿Se puede construir una matriz de antecedentes verificada","start":0,"end":3.226},{"text":"y un análisis preliminar solo con herramientas gratuitas?","start":3.226,"end":7.46175},{"text":"Sí, siempre que documente el proceso para poder repetirlo y declararlo.","start":7.46175,"end":12.624}]},{"scene":"etapas","index":0,"voice":"narrador","start":0,"dur":13.464,"chunks":[{"text":"Para buscar: Asta, Consensus y Google Scholar Labs.","start":0,"end":4.553583},{"text":"Para mapear: Connected Papers o ResearchRabbit.","start":4.553583,"end":8.214291},{"text":"Para leer y sintetizar con citas a sus fuentes: Gemini Notebook.","start":8.214291,"end":13.464}]},{"scene":"etapas","index":1,"voice":"narrador","start":0,"dur":18.36,"chunks":[{"text":"Para extraer: Elicit.","start":0,"end":2.576541},{"text":"Para analizar datos: Asta DataVoyager o los planes gratuitos de Claude o ChatGPT.","start":2.576541,"end":8.73725},{"text":"Para datos sensibles, un modelo local.","start":8.73725,"end":12.066333},{"text":"Y Zotero para las referencias.","start":12.066333,"end":14.732125},{"text":"Los límites de cada plan están en las tarjetas.","start":14.732125,"end":18.36}]},{"scene":"gratis","index":0,"voice":"narrador","start":0,"dur":11.784,"chunks":[{"text":"En los planes gratuitos,","start":0,"end":1.708166},{"text":"las conversaciones suelen usarse para mejorar los modelos y, a veces,","start":1.708166,"end":6.006625},{"text":"las leen revisores humanos: nunca suba allí datos personales o confidenciales.","start":6.006625,"end":11.784}]},{"scene":"gratis","index":1,"voice":"narrador","start":0,"dur":8.496,"chunks":[{"text":"Y como cambian límites y modelos sin aviso,","start":0,"end":2.830625},{"text":"guarde con fecha las salidas importantes: exportaciones, capturas y código.","start":2.830625,"end":8.496}]},{"scene":"pregunta","index":0,"voice":"narrador","start":0,"dur":19.344,"chunks":[{"text":"La parte A tiene cinco pasos.","start":0,"end":2.767875},{"text":"Primero, la pregunta estructurada: población, fenómeno, resultado y contexto.","start":2.767875,"end":8.979583},{"text":"El ejemplo del curso: en trabajadores urbanos de Colombia,","start":8.979583,"end":12.665833},{"text":"¿cómo afecta el aumento del salario mínimo a la informalidad laboral entre 2010 y","start":12.665833,"end":17.270416},{"text":"2025?","start":17.270416,"end":19.344}]},{"scene":"pregunta","index":1,"voice":"narrador","start":0,"dur":8.904,"chunks":[{"text":"Tiene 5 minutos para revisarla; luego vienen buscar, mapear, leer con fuentes y,","start":0,"end":5.751541},{"text":"por último, extraer y verificar.","start":5.751541,"end":8.904}]},{"scene":"buscar-mapear","index":0,"voice":"narrador","start":0,"dur":13.152,"chunks":[{"text":"Busque la misma pregunta en Asta y en Consensus, y en inglés en Google Scholar Labs.","start":0,"end":5.867333},{"text":"Registre consulta, fecha y resultados: con esa bitácora,","start":5.867333,"end":9.936208},{"text":"otra persona podría repetir la búsqueda.","start":9.936208,"end":13.152}]},{"scene":"buscar-mapear","index":1,"voice":"narrador","start":0,"dur":8.184,"chunks":[{"text":"Con el artículo más citado,","start":0,"end":1.925},{"text":"abra un grafo en Connected Papers","start":1.925,"end":3.634166},{"text":"y revise los trabajos fundacionales y las revisiones recientes.","start":3.634166,"end":8.184}]},{"scene":"leer","index":0,"voice":"narrador","start":0,"dur":13.056,"chunks":[{"text":"Cargue sus 5 a 8 PDF en un cuaderno de Gemini Notebook","start":0,"end":3.978583},{"text":"y pregunte qué métodos usan los estudios y en qué coinciden y difieren.","start":3.978583,"end":8.826541},{"text":"Pida además que cite el pasaje que respalda cada afirmación.","start":8.826541,"end":13.056}]},{"scene":"leer","index":1,"voice":"narrador","start":0,"dur":10.2,"chunks":[{"text":"Recuerde: la síntesis es tan buena como los documentos cargados.","start":0,"end":4.949},{"text":"Si deja fuera estudios clave, la conclusión hereda un sesgo de selección.","start":4.949,"end":10.2}]},{"scene":"matriz","index":0,"voice":"narrador","start":0,"dur":13.32,"chunks":[{"text":"Por último,","start":0,"end":1.032125},{"text":"llene la matriz de antecedentes y verifique tres filas con el protocolo del curso.","start":1.032125,"end":6.377541},{"text":"La columna «¿Verificada?» es evidencia de su control de calidad","start":6.377541,"end":9.96175},{"text":"y alimenta su declaración de uso de IA.","start":9.96175,"end":13.32}]},{"scene":"rutas","index":0,"voice":"narrador","start":0,"dur":15.384,"chunks":[{"text":"La parte B tiene tres rutas.","start":0,"end":2.869916},{"text":"En la primera, la de datos cuantitativos sin información personal,","start":2.869916,"end":6.951541},{"text":"suba el CSV del DANE a Asta DataVoyager o a un chat gratuito,","start":6.951541,"end":11.313791},{"text":"verifique a mano una cifra y guarde código y gráficos.","start":11.313791,"end":15.384}]},{"scene":"rutas","index":1,"voice":"narrador","start":0,"dur":7.56,"chunks":[{"text":"Revise la sección de métodos o el código línea por línea antes de usarlos:","start":0,"end":4.552541},{"text":"describen decisiones que usted firma.","start":4.552541,"end":7.56}]},{"scene":"ruta-2","index":0,"voice":"narrador","start":0,"dur":12.12,"chunks":[{"text":"En la segunda ruta, con entrevistas sintéticas o anonimizadas,","start":0,"end":4.220916},{"text":"entregue un libro de 4 a 6 códigos","start":4.220916,"end":6.618875},{"text":"y pida una primera codificación con la cita exacta que justifica cada código.","start":6.618875,"end":12.12}]},{"scene":"ruta-2","index":1,"voice":"narrador","start":0,"dur":10.968,"chunks":[{"text":"Luego codifique usted a mano una entrevista","start":0,"end":2.435208},{"text":"y calcule en qué porcentaje de fragmentos coinciden las dos codificaciones;","start":2.435208,"end":6.746416},{"text":"si tiene más tiempo, calcule también la kappa de Cohen.","start":6.746416,"end":10.968}]},{"scene":"ruta-2","index":2,"voice":"narrador","start":0,"dur":8.448,"chunks":[{"text":"La IA tiende a codificaciones literales y pierde ironías, contexto y silencios:","start":0,"end":5.343375},{"text":"el libro de códigos se ajusta en rondas.","start":5.343375,"end":8.448}]},{"scene":"ruta-3","index":0,"voice":"narrador","start":0,"dur":12.504,"chunks":[{"text":"En la tercera ruta, para datos sensibles,","start":0,"end":2.970916},{"text":"la misma tarea corre con LM Studio u Ollama y un modelo pequeño de pesos abiertos,","start":2.970916,"end":8.481125},{"text":"sin internet: los datos no salen del computador.","start":8.481125,"end":12.504}]},{"scene":"ruta-3","index":1,"voice":"narrador","start":0,"dur":13.68,"chunks":[{"text":"Según el programa del curso,","start":0,"end":1.96325},{"text":"con 16 GB de RAM sirven modelos de 8.000 a 12.000 millones de parámetros;","start":1.96325,"end":7.447958},{"text":"los tamaños de descarga están en la tarjeta.","start":7.447958,"end":10.739791},{"text":"Descargue el modelo antes de clase.","start":10.739791,"end":13.68}]},{"scene":"ruta-3","index":2,"voice":"narrador","start":0,"dur":9.84,"chunks":[{"text":"En Ollama, los modelos marcados como «cloud» no corren en su computador.","start":0,"end":5.114791},{"text":"Y un modelo pequeño se equivoca más: valide con más cuidado.","start":5.114791,"end":9.84}]},{"scene":"caso","index":0,"voice":"julian","start":0,"dur":6.12,"chunks":[{"text":"Yo sigo la ruta de datos cuantitativos con el archivo del DANE,","start":0,"end":3.328041},{"text":"y verifico a mano la tasa de una ciudad.","start":3.328041,"end":6.12}]},{"scene":"caso","index":1,"voice":"mariana","start":0,"dur":13.92,"chunks":[{"text":"Yo le pido a la IA una primera codificación de las entrevistas sintéticas","start":0,"end":4.0375},{"text":"y la comparo con la mía.","start":4.0375,"end":6.125},{"text":"Si el acuerdo no alcanza el umbral que fijamos, ajusto el libro de códigos,","start":6.125,"end":10.825},{"text":"no la instrucción para forzar el resultado.","start":10.825,"end":13.92}]},{"scene":"caso","index":2,"voice":"amparo","start":0,"dur":10.536,"chunks":[{"text":"Y las entrevistas reales del proyecto irán solo a un modelo local.","start":0,"end":4.732125},{"text":"Ahora dibujemos el flujo,","start":4.732125,"end":6.530625},{"text":"con un punto de control humano en cada etapa que lo necesite.","start":6.530625,"end":10.536}]},{"scene":"cierre","index":0,"voice":"narrador","start":0,"dur":11.736,"chunks":[{"text":"Las herramientas gratuitas permiten trabajar sin presupuesto,","start":0,"end":3.697958},{"text":"pero con menos capacidad: documente qué versión usó.","start":3.697958,"end":7.665833},{"text":"Y recuerde: la interpretación sigue siendo suya.","start":7.665833,"end":11.736}]}],"checkpoints":[],"pauses":[{"after":"caso","start":297.46799999999996,"end":303.46799999999996}]}};
